]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-pre-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-pre-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-pre-02','en-pre-02',null,0,2,'published',1,'{"id":"en-pre-02","baseId":"en-pre-02","revision":1,"level":"PRE","levelIndex":0,"order":2,"title":"Salomlashish va o‘zingizni tanishtirish","objective":"Qisqa salomlashasiz, ismingizni aytasiz va suhbatni yakunlaysiz.","context":"Ikki o‘quvchi yangi sinfda birinchi marta uchrashadi.","prerequisites":["en-pre-01"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi.","I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi.","Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi."],"pattern":"Hello. I’m … / Nice to meet you. / See you.","examples":["Hello. I am Lola.","Hi. I’m Ali.","Nice to meet you.","Good morning, teacher.","You are my classmate.","See you tomorrow."],"vocabulary":[{"id":"en-pre-02-v0","term":"hello","meaning":"salom","ipa":"/həˈləʊ/","collocation":"say hello","example":"Hello. I am Lola."},{"id":"en-pre-02-v1","term":"teacher","meaning":"o‘qituvchi","ipa":"/ˈtiːtʃə/","collocation":"my teacher","example":"Good morning, teacher."},{"id":"en-pre-02-v2","term":"classmate","meaning":"sinfdosh","ipa":"/ˈklɑːsmeɪt/","collocation":"a new classmate","example":"You are my classmate."},{"id":"en-pre-02-v3","term":"tomorrow","meaning":"ertaga","ipa":"/təˈmɒrəʊ/","collocation":"see you tomorrow","example":"See you tomorrow."}],"visuals":[{"kind":"dialogue","title":"Ma’no va tuzilish","items":["Hello. I’m … / Nice to meet you. / See you.","Hello. I am Lola.","Hi. I’m Ali."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Ikki o‘quvchi yangi sinfda birinchi marta uchrashadi.","Nice to meet you.","You are my classmate."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Good morning, teacher.","audio":"/english-course/v7.23/en-pre-02-dictation.mp3"},"exercises":[{"id":"en-pre-02-choice","type":"choice","skill":"grammar","prompt":"Ertalab o‘qituvchi bilan salomlashish uchun qaysi gap mos?","answers":["Good morning."],"explanation":"Morning ertalab degani.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["Good morning.","Good night.","Goodbye."]},{"id":"en-pre-02-gap","type":"grammarFill","skill":"grammar","prompt":"Nice to ___ you.","answers":["meet"],"explanation":"Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi. I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi. Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi.","hint":"Hello. I’m … / Nice to meet you. / See you."},{"id":"en-pre-02-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Hello. I am Lola."],"explanation":"Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi. I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi. Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi.","hint":"Hello. I’m … / Nice to meet you. / See you.","tokens":["Hello.","I","am","Lola."]},{"id":"en-pre-02-fix","type":"correction","skill":"grammar","prompt":"I is Lola.","answers":["I am Lola.","I’m Lola."],"explanation":"Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi. I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi. Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi.","hint":"Hello. I’m … / Nice to meet you. / See you."},{"id":"en-pre-02-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["salom","o‘qituvchi","sinfdosh","ertaga"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Hello. I’m … / Nice to meet you. / See you.","left":["hello","teacher","classmate","tomorrow"],"options":["salom","o‘qituvchi","sinfdosh","ertaga"]},{"id":"en-pre-02-picture","type":"picture","skill":"vocabulary","prompt":"“Book” yozilgan predmetni tanlang.","options":["book","clock","chair"],"answers":["book"],"hint":"Book — kitob.","explanation":"Kitobning sahifalari bor. Clock — soat, chair — stul."}],"reading":{"title":"Salomlashish va o‘zingizni tanishtirish — vaziyat","text":"Hello. I am Lola. Ali is my new classmate. We meet at school in the morning. I say, “Good morning, Ali.” He says, “Hi, Lola. Nice to meet you.” At the end of the lesson, we say, “See you tomorrow.”","sentences":["Hello.","I am Lola.","Ali is my new classmate.","We meet at school in the morning.","I say, “Good morning, Ali.","” He says, “Hi, Lola.","Nice to meet you.","” At the end of the lesson, we say, “See you tomorrow.","”"],"questions":[{"id":"en-pre-02-reading0","type":"choice","skill":"reading","prompt":"O‘quvchilar qayerda uchrashadi?","answers":["at school"],"explanation":"We meet at school — joy bevosita berilgan.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["at school","at home","at a shop"]},{"id":"en-pre-02-reading1","type":"choice","skill":"reading","prompt":"Qachon Good morning deyishadi?","answers":["in the morning"],"explanation":"Uchrashuv ertalab bo‘lib o‘tadi.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["in the morning","at night","after dinner"]},{"id":"en-pre-02-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["Hello.","I am Lola.","Ali is my new classmate.","We meet at school in the morning.","I say, “Good morning, Ali.","” He says, “Hi, Lola.","Nice to meet you.","” At the end of the lesson, we say, “See you tomorrow.","”"]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Good morning. I am your teacher. My name is Malika. This is your classmate, Ali. Please say hello. Nice to meet you, everyone.","audio":"/english-course/v7.23/en-pre-02.mp3","synthetic":true,"questions":[{"id":"en-pre-02-listening0","type":"choice","skill":"listening","prompt":"O‘qituvchining ismi nima?","answers":["Malika"],"explanation":"My name is Malika deyiladi.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["Malika","Lola","Maya"]},{"id":"en-pre-02-listening1","type":"choice","skill":"listening","prompt":"Sinfdoshning ismi nima?","answers":["Ali"],"explanation":"This is your classmate, Ali deyiladi.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["Ali","Vali","Bob"]},{"id":"en-pre-02-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Malika","Ali"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Hello. I’m … / Nice to meet you. / See you.","rows":["O‘qituvchi","Sinfdosh"]},{"id":"en-pre-02-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Good morning, teacher."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Hello. I’m … / Nice to meet you. / See you.","audio":"/english-course/v7.23/en-pre-02-dictation.mp3","transcript":"Good morning, teacher."}]},"writing":{"task":"Yangi sinfdoshingizga uch gapdan iborat tanishtirish xabarini yozing.","audience":"Sinfdagi sherigingiz","minWords":8,"maxWords":40,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Hello. I am Aziz. I am your new classmate. Nice to meet you.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["Hello. I am Lola.","Hi. I’m Ali.","Nice to meet you."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Yangi sinfdosh bilan uchrashuvni o‘ynang: salomlashish, ism, javob va xayrlashish.","seconds":20,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Yangi sinfdoshingizga uch gapdan iborat tanishtirish xabarini yozing.","exit":[[{"id":"en-pre-02-exit0","type":"grammarFill","skill":"grammar","prompt":"I ___ Ali.","answers":["am"],"explanation":"Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi. I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi. Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi.","hint":"Hello. I’m … / Nice to meet you. / See you."},{"id":"en-pre-02-exit1","type":"grammarFill","skill":"grammar","prompt":"Nice to ___ you.","answers":["meet"],"explanation":"Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi. I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi. Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi.","hint":"Hello. I’m … / Nice to meet you. / See you."},{"id":"en-pre-02-exit2","type":"grammarFill","skill":"grammar","prompt":"See you ___.","answers":["tomorrow"],"explanation":"Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi. I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi. Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi.","hint":"Hello. I’m … / Nice to meet you. / See you."},{"id":"en-pre-02-exit3","type":"choice","skill":"grammar","prompt":"I’m nimaning qisqartmasi?","answers":["I am"],"explanation":"Apostrof tushirilgan harfni bildiradi.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["I am","I is","I has"]},{"id":"en-pre-02-exit4","type":"choice","skill":"grammar","prompt":"Xayrlashish uchun gap tanlang.","answers":["Goodbye."],"explanation":"Goodbye suhbatni yakunlaydi.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["Goodbye.","Nice to meet you.","What is it?"]}],[{"id":"en-pre-02-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Hi. I’m Ali."],"explanation":"Hello b