insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-16','en-b2-16',null,4,16,'published',1,'{"id":"en-b2-16","baseId":"en-b2-16","revision":1,"level":"B2","levelIndex":4,"order":16,"title":"Concession, purpose va result","objective":"Qarshi dalil, maqsad va oqibatni bog‘lovchi bilan aniq ajratasiz.","context":"Concession, purpose va result","prerequisites":["en-b2-15"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Although/even though + clause; despite/in spite of + noun yoki -ing.","So that + clause maqsad; so/such … that natija.","Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang."],"pattern":"although it is costly / despite the cost / so that / so useful that","examples":["Although the plan is costly, it may help.","Despite the cost, we support a trial.","We added labels so that visitors could navigate.","The room was so busy that we waited.","It was such a useful guide that we shared it.","Even though opinions differ, we can agree on a trial."],"vocabulary":[{"id":"en-b2-16-v0","term":"concession","meaning":"yon beruvchi dalil","ipa":"/kənˈseʃən/","collocation":"make a concession","example":"make a concession"},{"id":"en-b2-16-v1","term":"purpose","meaning":"maqsad","ipa":"/ˈpɜːpəs/","collocation":"state a purpose","example":"A reasoned report separates the purpose of a trial from the consequence of a past event."},{"id":"en-b2-16-v2","term":"consequence","meaning":"oqibat","ipa":"/ˈkɒnsɪkwəns/","collocation":"a likely consequence","example":"A reasoned report separates the purpose of a trial from the consequence of a past event."},{"id":"en-b2-16-v3","term":"trial","meaning":"sinov","ipa":"/ˈtraɪəl/","collocation":"a limited trial","example":"Despite the cost, we support a trial."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["although it is costly / despite the cost / so that / so useful that","Although the plan is costly, it may help.","Despite the cost, we support a trial."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Students need quiet space, but costs matter.","A short trial can collect attendance data.","Use the evidence to decide rather than assume."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The room was so busy that we waited.","audio":"/english-course/v7.23/en-b2-16-dictation.mp3"},"exercises":[{"id":"en-b2-16-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: ___ the cost, we support a trial.","answers":["Despite"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that","options":["Despite","Although","However"]},{"id":"en-b2-16-gap","type":"grammarFill","skill":"grammar","prompt":"___ the cost, we support a trial.","answers":["Despite"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Although the plan is costly, it may help."],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that","tokens":["Although","the","plan","is","costly,","it","may","help."]},{"id":"en-b2-16-fix","type":"correction","skill":"grammar","prompt":"Despite of the cost, we support a trial.","answers":["Despite the cost, we support a trial."],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["yon beruvchi dalil","maqsad","oqibat","sinov"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"although it is costly / despite the cost / so that / so useful that","left":["concession","purpose","consequence","trial"],"options":["yon beruvchi dalil","maqsad","oqibat","sinov"]},{"id":"en-b2-16-transform","type":"transformation","skill":"grammar","prompt":"Despite bilan: Although the plan is costly, we support it.","answers":["Despite the cost, we support the plan."],"hint":"although it is costly / despite the cost / so that / so useful that","explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing."},{"id":"en-b2-16-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Students need quiet space, but costs matter.","A short trial can collect attendance data.","Use the evidence to decide rather than assume."],"answers":["Students need quiet space, but costs matter.\nA short trial can collect attendance data.\nUse the evidence to decide rather than assume."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-16-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["Although the plan is costly, it may help."],"tokens":["Although","the","plan","is","costly,","it","may","help."],"hint":"although it is costly / despite the cost / so that / so useful that","explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing."},{"id":"en-b2-16-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Reduced relative va participle clauses: Til vositasini tanlang: Students ___ outside need tickets. (wait)","answers":["waiting"],"explanation":"Students waiting outside = students who are waiting; books written recently passive ma’no. Having checked the list, we … avvalgi amal, asosiy gap egasi bir xil bo‘lishi kerak. Dangling participle: Walking home, the rain began — yomg‘ir yurmagan; egani tuzating.","hint":"waiting outside / written recently / having checked","options":["waiting","wait","waited"],"recap":true,"sourceLesson":"Reduced relative va participle clauses"},{"id":"en-b2-16-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Gerund va infinitive: ma’no o‘zgarishi: Til vositasini tanlang: Remember ___ lock the door.","answers":["to"],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk","options":["to","for","that"],"recap":true,"sourceLesson":"Gerund va infinitive: ma’no o‘zgarishi"},{"id":"en-b2-16-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Articles va determiners: umumiydan aniqga: Til vositasini tanlang: We received ___ proposal.","answers":["a"],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student","options":["a","an","no article"],"recap":true,"sourceLesson":"Articles va determiners: umumiydan aniqga"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The school considers extending library hours. Although the plan would cost money, supporters argue that students need a quiet place after lessons. Critics agree with the aim but question whether enough students would attend. The school proposes a two-week trial so that it can collect attendance data before making a permanent decision. Last year, a popular event was so busy that the room became difficult to use. That result does not prove every extended session will be crowded. A reasoned report separates the purpose of a trial from the consequence of a past event. It also acknowledges the cost without treating it as a complete argument against the plan. Shared aims can make disagreement more productive when the uncertain facts are tested.","sentences":["The school considers extending library hours.","Although the plan would cost money, supporters argue that students need a quiet place after lessons.","Critics agree with the aim but question whether enough students would attend.","The school proposes a two-week trial so that it can collect attendance data before making a permanent decision.","Last year, a popular event was so busy that the room became difficult to use.","That result does not prove every extended session will be crowded.","A reasoned report separates the purpose of a trial from the consequence of a past event.","It also acknowledges the cost without treating it as a complete argument against the plan.","Shared aims can make disagreement more productive when the uncertain facts are tested."],"questions":[{"id":"en-b2-16-reading0","type":"choice","skill":"reading","prompt":"Trial maqsadi?","answers":["collect attendance evidence"],"explanation":"So that maqsad.","hint":"although it is costly / despite the cost / so that / so useful that","options":["collect attendance evidence","prove every day is crowded","avoid every cost"]},{"id":"en-b2-16-reading1","type":"choice","skill":"reading","prompt":"Critics nimaga rozi?","answers":["the need for a quiet place"],"explanation":"Aimga rozi, attendancega shubha.","hint":"although it is costly / despite the cost / so that / so useful that","options":["the need for a quiet place","all costs are irrelevant","every session will be busy"]},{"id":"en-b2-16-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"although it is costly / despite the cost / so that / so useful that","options":["The school considers extending library hours.","Although the plan would cost money, supporters argue that students need a quiet place after lessons.","Critics agree with the aim but question whether enough students would attend.","The school proposes a two-week trial so that it can collect attendance data before making a permanent decision.","Last year, a popular event was so busy that the room became difficult to use.","That result does not prove every extended session will be crowded.","A reasoned report separates the purpose of a trial from the consequence of a past event.","It also acknowledges the cost without treating it as a complete argument against the plan.","Shared aims can make disagreement more productive when the uncertain facts are tested."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is trial. The school considers extending library hours. Although the plan would cost money, supporters argue that students need a quiet place after lessons. Speaker two: My main point is evidence. A shared aim still needs evidence about likely attendance. The school considers extending library hours. Although the plan would cost money, supporters argue that students need a quiet place after lessons. Critics agree with the aim but question whether enough students would attend. The school proposes a two-week trial so that it can collect attendance data before making a permanent decision. Last year, a popular event was so busy that the room became difficult to use. That result does not prove every extended session will be crowded. A reasoned report separates the purpose of a trial from the consequence of a past event. It also acknowledges the cost without treating it as a complete argument against the plan. Shared aims can make disagreement more productive when the uncertain facts are tested.","audio":"/english-course/v7.23/en-b2-16.mp3","synthetic":true,"questions":[{"id":"en-b2-16-listening0","type":"choice","skill":"listening","prompt":"Trial maqsadi?","answers":["collect attendance evidence"],"explanation":"So that maqsad.","hint":"although it is costly / despite the cost / so that / so useful that","options":["collect attendance evidence","prove every day is crowded","avoid every cost"]},{"id":"en-b2-16-listening1","type":"choice","skill":"listening","prompt":"Critics nimaga rozi?","answers":["the need for a quiet place"],"explanation":"Aimga rozi, attendancega shubha.","hint":"although it is costly / despite the cost / so that / so useful that","options":["the need for a quiet place","all costs are irrelevant","every session will be busy"]},{"id":"en-b2-16-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["trial","evidence"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"although it is costly / despite the cost / so that / so useful that","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-16-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The room was so busy that we waited."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"although it is costly / despite the cost / so that / so useful that","audio":"/english-course/v7.23/en-b2-16-dictation.mp3","transcript":"The room was so busy that we waited."}]},"writing":{"task":"Advantages/disadvantages matnida qarshi dalil, maqsad va natijani ajrating.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Although longer library hours would cost money, they could provide a quiet place for students after lessons. Critics reasonably ask whether enough students would attend. We propose a two-week trial so that attendance can be measured before a permanent decision is made. The success of one crowded event should not be treated as proof that every session will be busy. Despite the uncertainty, a limited trial offers a practical way to compare the benefit with the cost. The aim is to test the plan, rather than win an argument through repetition.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["Although the plan is costly, it may help.","Despite the cost, we support a trial.","We added labels so that visitors could navigate."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Advantages/disadvantages matnida qarshi dalil, maqsad va natijani ajrating. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Advantages/disadvantages matnida qarshi dalil, maqsad va natijani ajrating.","exit":[[{"id":"en-b2-16-exit0","type":"grammarFill","skill":"grammar","prompt":"___ the cost, we support a trial.","answers":["Despite"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-exit1","type":"grammarFill","skill":"grammar","prompt":"We added labels so ___ visitors could navigate.","answers":["that"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-exit2","type":"grammarFill","skill":"grammar","prompt":"It was ___ useful that we shared it.","answers":["so"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-exit3","type":"choice","skill":"grammar","prompt":"Trial maqsadi?","answers":["collect attendance evidence"],"explanation":"So that maqsad.","hint":"although it is costly / despite the cost / so that / so useful that","options":["collect attendance evidence","prove every day is crowded","avoid every cost"]},{"id":"en-b2-16-exit4","type":"choice","skill":"grammar","prompt":"Critics nimaga rozi?","answers":["the need for a quiet place"],"explanation":"Aimga rozi, attendancega shubha.","hint":"although it is costly / despite the cost / so that / so useful that","options":["the need for a quiet place","all costs are irrelevant","every session will be busy"]}],[{"id":"en-b2-16-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Despite the cost, we support a trial."],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that","tokens":["Despite","the","cost,","we","support","a","trial."]},{"id":"en-b2-16-exit-b1","type":"grammarFill","skill":"grammar","prompt":"We added labels so ___ visitors could navigate.","answers":["that"],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that"},{"id":"en-b2-16-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The room was so busy that we waited."],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that","tokens":["The","room","was","so","busy","that","we","waited."]},{"id":"en-b2-16-exit-b3","type":"choice","skill":"grammar","prompt":"Trial maqsadi?","answers":["collect attendance evidence"],"explanation":"So that maqsad.","hint":"although it is costly / despite the cost / so that / so useful that","options":["collect attendance evidence","prove every day is crowded","avoid every cost"]},{"id":"en-b2-16-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Even though opinions differ, we can agree on a trial."],"explanation":"Although/even though + clause; despite/in spite of + noun yoki -ing. So that + clause maqsad; so/such … that natija. Despite of emas. Although va butni bitta asosiy juftlikda takrorlamang.","hint":"although it is costly / despite the cost / so that / so useful that","tokens":["Even","though","opinions","differ,","we","can","agree","on","a","trial."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-16","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-b2-16-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Reduced relative va participle clauses: Til vositasini tanlang: Students ___ outside need tickets. (wait)","answers":["waiting"],"explanation":"Students waiting outside = students who are waiting; books written recently passive ma’no. Having checked the list, we … avvalgi amal, asosiy gap egasi bir xil bo‘lishi kerak. Dangling participle: Walking home, the rain began — yomg‘ir yurmagan; egani tuzating.","hint":"waiting outside / written recently / having checked","options":["waiting","wait","waited"],"recap":true,"sourceLesson":"Reduced relative va participle clauses"},{"id":"en-b2-16-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Gerund va infinitive: ma’no o‘zgarishi: Til vositasini tanlang: Remember ___ lock the door.","answers":["to"],"explanation":"Remember doing — o‘tgan ish xotirasi; remember to do — bajarishni unutmaslik. Stop doing — faoliyatni to‘xtatish; stop to do — boshqa ishni bajarish uchun to‘xtash. Try doing — usulni sinash; try to do — harakat qilib bajarishga urinish.","hint":"remember locking / remember to lock / stop to talk","options":["to","for","that"],"recap":true,"sourceLesson":"Gerund va infinitive: ma’no o‘zgarishi"},{"id":"en-b2-16-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Articles va determiners: umumiydan aniqga: Til vositasini tanlang: We received ___ proposal.","answers":["a"],"explanation":"A/an yangi sanaladigan birlik; the suhbatdan yoki vaziyatdan aniqlangan obyekt. Ko‘plik va sanalmaydigan ot bilan umumiy ma’noda zero article: libraries, information. Each/every birlik; both/all guruh; an tovushga qarab: an hour, a university.","hint":"a proposal → the proposal / information / each student","options":["a","an","no article"],"recap":true,"sourceLesson":"Articles va determiners: umumiydan aniqga"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-17','en-b2-17',null,4,17,'published',1,'{"id":"en-b2-17","baseId":"en-b2-17","revision":1,"level":"B2","levelIndex":4,"order":17,"title":"Odobli e’tiroz va hedging","objective":"Fikrni yumshatib, dalil kuchiga mos aniqlik bilan bahslashasiz.","context":"Odobli e’tiroz va hedging","prerequisites":["en-b2-16"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["May/might, tends to, appears to xulosa kuchini chegaralaydi.","I see your point, but … kelishilgan qismdan e’tirozga o‘tadi.","Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin."],"pattern":"appears to / may suggest / I see your point, but","examples":["The result appears to support the plan.","This may suggest a useful pattern.","I see your point, but the sample is small.","The method tends to work better with clear instructions.","Could we consider another explanation?","I am not convinced that cost alone decides it."],"vocabulary":[{"id":"en-b2-17-v0","term":"sample","meaning":"namuna","ipa":"/ˈsɑːmpəl/","collocation":"a small sample","example":"I see your point, but the sample is small."},{"id":"en-b2-17-v1","term":"tentative","meaning":"dastlabki","ipa":"/ˈtentətɪv/","collocation":"a tentative conclusion","example":"a tentative conclusion"},{"id":"en-b2-17-v2","term":"challenge","meaning":"shubha ostiga qo‘ymoq","ipa":"/ˈtʃælɪndʒ/","collocation":"challenge a claim","example":"challenge a claim"},{"id":"en-b2-17-v3","term":"courteous","meaning":"hurmatli","ipa":"/ˈkɜːtiəs/","collocation":"a courteous disagreement","example":"Her objection is courteous because she recognises the useful work already done and proposes a larger survey."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["appears to / may suggest / I see your point, but","The result appears to support the plan.","This may suggest a useful pattern."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The early result is encouraging.","Only eight volunteers answered.","Keep the trial and gather broader evidence."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The method tends to work better with clear instructions.","audio":"/english-course/v7.23/en-b2-17-dictation.mp3"},"exercises":[{"id":"en-b2-17-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The result appears ___ support the plan.","answers":["to"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","options":["to","for","that"]},{"id":"en-b2-17-gap","type":"grammarFill","skill":"grammar","prompt":"The result appears ___ support the plan.","answers":["to"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The result appears to support the plan."],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","tokens":["The","result","appears","to","support","the","plan."]},{"id":"en-b2-17-fix","type":"correction","skill":"grammar","prompt":"Eight volunteers prove that every student agrees.","answers":["Eight volunteers suggest support, but do not prove that every student agrees."],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["namuna","dastlabki","shubha ostiga qo‘ymoq","hurmatli"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"appears to / may suggest / I see your point, but","left":["sample","tentative","challenge","courteous"],"options":["namuna","dastlabki","shubha ostiga qo‘ymoq","hurmatli"]},{"id":"en-b2-17-transform","type":"transformation","skill":"grammar","prompt":"Ehtiyotkor qiling: The findings prove the plan works.","answers":["The findings may suggest that the plan works."],"hint":"appears to / may suggest / I see your point, but","explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi."},{"id":"en-b2-17-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The early result is encouraging.","Only eight volunteers answered.","Keep the trial and gather broader evidence."],"answers":["The early result is encouraging.\nOnly eight volunteers answered.\nKeep the trial and gather broader evidence."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A survey of eight volunteers finds that most prefer the new reading corner. The organiser announces that all students clearly support it. Another student agrees that the result is encouraging but points out that the sample is small and voluntary. She says the findings may suggest a useful pattern, not prove a school-wide preference. This wording limits the claim to what the evidence supports. Her objection is courteous because she recognises the useful work already done and proposes a larger survey. Hedging is not an excuse to avoid taking a position. The student still recommends keeping the corner during the trial. She simply separates a practical recommendation from a certainty the survey cannot establish.","sentences":["A survey of eight volunteers finds that most prefer the new reading corner.","The organiser announces that all students clearly support it.","Another student agrees that the result is encouraging but points out that the sample is small and voluntary.","She says the findings may suggest a useful pattern, not prove a school-wide preference.","This wording limits the claim to what the evidence supports.","Her objection is courteous because she recognises the useful work already done and proposes a larger survey.","Hedging is not an excuse to avoid taking a position.","The student still recommends keeping the corner during the trial.","She simply separates a practical recommendation from a certainty the survey cannot establish."],"questions":[{"id":"en-b2-17-reading0","type":"choice","skill":"reading","prompt":"Survey nega umumiy xulosaga yetmaydi?","answers":["the sample is small and voluntary"],"explanation":"Kichik o‘z ixtiyoriy tanlov.","hint":"appears to / may suggest / I see your point, but","options":["the sample is small and voluntary","eight is always zero","no one answered"]},{"id":"en-b2-17-reading1","type":"choice","skill":"reading","prompt":"Student qanday pozitsiya oladi?","answers":["keep the trial while gathering better evidence"],"explanation":"Tavsiyasi aniq, xulosasi cheklangan.","hint":"appears to / may suggest / I see your point, but","options":["keep the trial while gathering better evidence","close immediately","claim certainty"]},{"id":"en-b2-17-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"appears to / may suggest / I see your point, but","options":["A survey of eight volunteers finds that most prefer the new reading corner.","The organiser announces that all students clearly support it.","Another student agrees that the result is encouraging but points out that the sample is small and voluntary.","She says the findings may suggest a useful pattern, not prove a school-wide preference.","This wording limits the claim to what the evidence supports.","Her objection is courteous because she recognises the useful work already done and proposes a larger survey.","Hedging is not an excuse to avoid taking a position.","The student still recommends keeping the corner during the trial.","She simply separates a practical recommendation from a certainty the survey cannot establish."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is sample. A survey of eight volunteers finds that most prefer the new reading corner. The organiser announces that all students clearly support it. Speaker two: My main point is tentative. The result is encouraging, but the conclusion should remain tentative. A survey of eight volunteers finds that most prefer the new reading corner. The organiser announces that all students clearly support it. Another student agrees that the result is encouraging but points out that the sample is small and voluntary. She says the findings may suggest a useful pattern, not prove a school-wide preference. This wording limits the claim to what the evidence supports. Her objection is courteous because she recognises the useful work already done and proposes a larger survey. Hedging is not an excuse to avoid taking a position. The student still recommends keeping the corner during the trial. She simply separates a practical recommendation from a certainty the survey cannot establish.","audio":"/english-course/v7.23/en-b2-17.mp3","synthetic":true,"questions":[{"id":"en-b2-17-listening0","type":"choice","skill":"listening","prompt":"Survey nega umumiy xulosaga yetmaydi?","answers":["the sample is small and voluntary"],"explanation":"Kichik o‘z ixtiyoriy tanlov.","hint":"appears to / may suggest / I see your point, but","options":["the sample is small and voluntary","eight is always zero","no one answered"]},{"id":"en-b2-17-listening1","type":"choice","skill":"listening","prompt":"Student qanday pozitsiya oladi?","answers":["keep the trial while gathering better evidence"],"explanation":"Tavsiyasi aniq, xulosasi cheklangan.","hint":"appears to / may suggest / I see your point, but","options":["keep the trial while gathering better evidence","close immediately","claim certainty"]},{"id":"en-b2-17-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["sample","tentative"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"appears to / may suggest / I see your point, but","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-17-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The method tends to work better with clear instructions."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"appears to / may suggest / I see your point, but","audio":"/english-course/v7.23/en-b2-17-dictation.mp3","transcript":"The method tends to work better with clear instructions."}]},"writing":{"task":"Kichik surveyga asoslangan xulosani cheklov va amaliy tavsiya bilan yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The survey result is encouraging: most of the eight volunteers preferred the reading corner. However, the sample is too small and selective to establish the view of all students. I recommend keeping the corner during the trial while collecting responses from a broader group. This position recognises the benefit already observed without claiming more than the evidence supports. I see the organiser’s point about enthusiasm, but we should distinguish support among volunteers from school-wide demand. A larger survey could help decide whether the arrangement should become permanent.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The result appears to support the plan.","This may suggest a useful pattern.","I see your point, but the sample is small."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Kichik surveyga asoslangan xulosani cheklov va amaliy tavsiya bilan yozing. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Kichik surveyga asoslangan xulosani cheklov va amaliy tavsiya bilan yozing.","exit":[[{"id":"en-b2-17-exit0","type":"grammarFill","skill":"grammar","prompt":"The result appears ___ support the plan.","answers":["to"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-exit1","type":"grammarFill","skill":"grammar","prompt":"This ___ suggest a pattern. (ehtimol)","answers":["may"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-exit2","type":"grammarFill","skill":"grammar","prompt":"I see your point, ___ the sample is small.","answers":["but"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-exit3","type":"choice","skill":"grammar","prompt":"Survey nega umumiy xulosaga yetmaydi?","answers":["the sample is small and voluntary"],"explanation":"Kichik o‘z ixtiyoriy tanlov.","hint":"appears to / may suggest / I see your point, but","options":["the sample is small and voluntary","eight is always zero","no one answered"]},{"id":"en-b2-17-exit4","type":"choice","skill":"grammar","prompt":"Student qanday pozitsiya oladi?","answers":["keep the trial while gathering better evidence"],"explanation":"Tavsiyasi aniq, xulosasi cheklangan.","hint":"appears to / may suggest / I see your point, but","options":["keep the trial while gathering better evidence","close immediately","claim certainty"]}],[{"id":"en-b2-17-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["This may suggest a useful pattern."],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","tokens":["This","may","suggest","a","useful","pattern."]},{"id":"en-b2-17-exit-b1","type":"grammarFill","skill":"grammar","prompt":"This ___ suggest a pattern. (ehtimol)","answers":["may"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but"},{"id":"en-b2-17-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The method tends to work better with clear instructions."],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","tokens":["The","method","tends","to","work","better","with","clear","instructions."]},{"id":"en-b2-17-exit-b3","type":"choice","skill":"grammar","prompt":"Survey nega umumiy xulosaga yetmaydi?","answers":["the sample is small and voluntary"],"explanation":"Kichik o‘z ixtiyoriy tanlov.","hint":"appears to / may suggest / I see your point, but","options":["the sample is small and voluntary","eight is always zero","no one answered"]},{"id":"en-b2-17-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I am not convinced that cost alone decides it."],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","tokens":["I","am","not","convinced","that","cost","alone","decides","it."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-17","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-18','en-b2-18',null,4,18,'published',1,'{"id":"en-b2-18","baseId":"en-b2-18","revision":1,"level":"B2","levelIndex":4,"order":18,"title":"Register: formal email va samimiy xabar","objective":"Bitta maqsadni auditoriyaga mos ikki uslubda ifodalaysiz.","context":"Register: formal email va samimiy xabar","prerequisites":["en-b2-17"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas.","Could you please … va I would appreciate … so‘rovni yumshatadi.","Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning."],"pattern":"Could you please clarify …? / Can you tell me …?","examples":["Could you please clarify the deadline?","I would appreciate a written reply.","Please find the revised plan attached.","Can you tell me when it is due?","Thanks for checking this for me.","I am writing to request more information."],"vocabulary":[{"id":"en-b2-18-v0","term":"clarify","meaning":"aniqlashtirmoq","ipa":"/ˈklærɪfaɪ/","collocation":"clarify a deadline","example":"Could you please clarify the deadline?"},{"id":"en-b2-18-v1","term":"attached","meaning":"ilova qilingan","ipa":"/əˈtætʃt/","collocation":"the attached plan","example":"Please find the revised plan attached."},{"id":"en-b2-18-v2","term":"recipient","meaning":"qabul qiluvchi","ipa":"/rɪˈsɪpiənt/","collocation":"a message recipient","example":"a message recipient"},{"id":"en-b2-18-v3","term":"tone","meaning":"ohang","ipa":"/təʊn/","collocation":"a respectful tone","example":"a respectful tone"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["Could you please clarify …? / Can you tell me …?","Could you please clarify the deadline?","I would appreciate a written reply."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The recipient needs a clear request.","The notice omits the submission deadline.","Ask one precise question in a respectful tone."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Can you tell me when it is due?","audio":"/english-course/v7.23/en-b2-18-dictation.mp3"},"exercises":[{"id":"en-b2-18-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Could you please ___ the deadline? (clarify)","answers":["clarify"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?","options":["clarify","clarifying","clarified"]},{"id":"en-b2-18-gap","type":"grammarFill","skill":"grammar","prompt":"Could you please ___ the deadline? (clarify)","answers":["clarify"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Could you please clarify the deadline?"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?","tokens":["Could","you","please","clarify","the","deadline?"]},{"id":"en-b2-18-fix","type":"correction","skill":"grammar","prompt":"Tell me the date now, office.","answers":["Could you please clarify the deadline?"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["aniqlashtirmoq","ilova qilingan","qabul qiluvchi","ohang"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Could you please clarify …? / Can you tell me …?","left":["clarify","attached","recipient","tone"],"options":["aniqlashtirmoq","ilova qilingan","qabul qiluvchi","ohang"]},{"id":"en-b2-18-transform","type":"transformation","skill":"grammar","prompt":"Formal qiling: Tell me when it is due.","answers":["Could you please clarify the deadline?"],"hint":"Could you please clarify …? / Can you tell me …?","explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas."},{"id":"en-b2-18-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The recipient needs a clear request.","The notice omits the submission deadline.","Ask one precise question in a respectful tone."],"answers":["The recipient needs a clear request.\nThe notice omits the submission deadline.\nAsk one precise question in a respectful tone."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-18-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["clarify","attached","recipient","tone"],"options":["clarify a deadline","the attached plan","a message recipient","a respectful tone"],"answers":["clarify a deadline","the attached plan","a message recipient","a respectful tone"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."},{"id":"en-b2-18-register","type":"register","skill":"writing","prompt":"Maktab ofisiga rasmiy so‘rovni tanlang.","options":["Could you please clarify the deadline?","Tell me now!","Hey, what’s up?"],"answers":["Could you please clarify the deadline?"],"hint":"Murojaat va so‘rov hurmatli bo‘lsin.","explanation":"Could you please … aniq va hurmatli rasmiy so‘rov."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Two emails ask for the same deadline. A message to a friend says, “Can you tell me when it is due?” A message to the school office says, “Could you please clarify the submission deadline?” The second is not better English in every situation; it suits a different relationship. A student initially writes a very long formal email with several vague phrases and no clear request. The teacher asks her to simplify it. She keeps a polite greeting, states the purpose, and asks one precise question. Register includes clarity as well as politeness. Choosing an audience does not require hiding meaning behind elaborate words. The office can answer more quickly because the revised message makes the requested action easy to identify.","sentences":["Two emails ask for the same deadline.","A message to a friend says, “Can you tell me when it is due?","” A message to the school office says, “Could you please clarify the submission deadline?","” The second is not better English in every situation; it suits a different relationship.","A student initially writes a very long formal email with several vague phrases and no clear request.","The teacher asks her to simplify it.","She keeps a polite greeting, states the purpose, and asks one precise question.","Register includes clarity as well as politeness.","Choosing an audience does not require hiding meaning behind elaborate words.","The office can answer more quickly because the revised message makes the requested action easy to identify."],"questions":[{"id":"en-b2-18-reading0","type":"choice","skill":"reading","prompt":"Ikkinchi xabar nega mos?","answers":["it suits the office relationship"],"explanation":"Auditoriya register tanlaydi.","hint":"Could you please clarify …? / Can you tell me …?","options":["it suits the office relationship","it is always superior","it must be longer"]},{"id":"en-b2-18-reading1","type":"choice","skill":"reading","prompt":"Uzun email muammosi?","answers":["the request was unclear"],"explanation":"Murakkablik aniqlikni yo‘qotgan.","hint":"Could you please clarify …? / Can you tell me …?","options":["the request was unclear","it contained a greeting","it asked one precise question"]},{"id":"en-b2-18-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Could you please clarify …? / Can you tell me …?","options":["Two emails ask for the same deadline.","A message to a friend says, “Can you tell me when it is due?","” A message to the school office says, “Could you please clarify the submission deadline?","” The second is not better English in every situation; it suits a different relationship.","A student initially writes a very long formal email with several vague phrases and no clear request.","The teacher asks her to simplify it.","She keeps a polite greeting, states the purpose, and asks one precise question.","Register includes clarity as well as politeness.","Choosing an audience does not require hiding meaning behind elaborate words.","The office can answer more quickly because the revised message makes the requested action easy to identify."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is recipient. Two emails ask for the same deadline. A message to a friend says, “Can you tell me when it is due? Speaker two: My main point is clarity. A formal request should remain easy to understand. Two emails ask for the same deadline. A message to a friend says, “Can you tell me when it is due?” A message to the school office says, “Could you please clarify the submission deadline?” The second is not better English in every situation; it suits a different relationship. A student initially writes a very long formal email with several vague phrases and no clear request. The teacher asks her to simplify it. She keeps a polite greeting, states the purpose, and asks one precise question. Register includes clarity as well as politeness. Choosing an audience does not require hiding meaning behind elaborate words. The office can answer more quickly because the revised message makes the requested action easy to identify.","audio":"/english-course/v7.23/en-b2-18.mp3","synthetic":true,"questions":[{"id":"en-b2-18-listening0","type":"choice","skill":"listening","prompt":"Ikkinchi xabar nega mos?","answers":["it suits the office relationship"],"explanation":"Auditoriya register tanlaydi.","hint":"Could you please clarify …? / Can you tell me …?","options":["it suits the office relationship","it is always superior","it must be longer"]},{"id":"en-b2-18-listening1","type":"choice","skill":"listening","prompt":"Uzun email muammosi?","answers":["the request was unclear"],"explanation":"Murakkablik aniqlikni yo‘qotgan.","hint":"Could you please clarify …? / Can you tell me …?","options":["the request was unclear","it contained a greeting","it asked one precise question"]},{"id":"en-b2-18-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["recipient","clarity"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Could you please clarify …? / Can you tell me …?","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-18-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Can you tell me when it is due?"],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Could you please clarify …? / Can you tell me …?","audio":"/english-course/v7.23/en-b2-18-dictation.mp3","transcript":"Can you tell me when it is due?"}]},"writing":{"task":"Bir so‘rovni do‘stga va maktab ofisiga mos ikki xabarda yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Dear school office, I am writing to ask about the deadline for submitting our club proposal. The notice gives the meeting date but does not state when proposals should arrive. Could you please clarify the submission deadline and confirm whether an electronic copy is acceptable? We would like to plan the final review before sending our work. I would appreciate a written reply so that I can share the information accurately with the group. Thank you for your help. Kind regards, Lola.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["Could you please clarify the deadline?","I would appreciate a written reply.","Please find the revised plan attached."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Bir so‘rovni do‘stga va maktab ofisiga mos ikki xabarda yozing. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Bir so‘rovni do‘stga va maktab ofisiga mos ikki xabarda yozing.","exit":[[{"id":"en-b2-18-exit0","type":"grammarFill","skill":"grammar","prompt":"Could you please ___ the deadline? (clarify)","answers":["clarify"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-exit1","type":"grammarFill","skill":"grammar","prompt":"I would appreciate ___ written reply.","answers":["a"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-exit2","type":"grammarFill","skill":"grammar","prompt":"Please find the plan ___. (attach)","answers":["attached"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-exit3","type":"choice","skill":"grammar","prompt":"Ikkinchi xabar nega mos?","answers":["it suits the office relationship"],"explanation":"Auditoriya register tanlaydi.","hint":"Could you please clarify …? / Can you tell me …?","options":["it suits the office relationship","it is always superior","it must be longer"]},{"id":"en-b2-18-exit4","type":"choice","skill":"grammar","prompt":"Uzun email muammosi?","answers":["the request was unclear"],"explanation":"Murakkablik aniqlikni yo‘qotgan.","hint":"Could you please clarify …? / Can you tell me …?","options":["the request was unclear","it contained a greeting","it asked one precise question"]}],[{"id":"en-b2-18-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I would appreciate a written reply."],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?","tokens":["I","would","appreciate","a","written","reply."]},{"id":"en-b2-18-exit-b1","type":"grammarFill","skill":"grammar","prompt":"I would appreciate ___ written reply.","answers":["a"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?"},{"id":"en-b2-18-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Can you tell me when it is due?"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?","tokens":["Can","you","tell","me","when","it","is","due?"]},{"id":"en-b2-18-exit-b3","type":"choice","skill":"grammar","prompt":"Ikkinchi xabar nega mos?","answers":["it suits the office relationship"],"explanation":"Auditoriya register tanlaydi.","hint":"Could you please clarify …? / Can you tell me …?","options":["it suits the office relationship","it is always superior","it must be longer"]},{"id":"en-b2-18-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I am writing to request more information."],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?","tokens":["I","am","writing","to","request","more","information."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-18","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-19','en-b2-19',null,4,19,'published',1,'{"id":"en-b2-19","baseId":"en-b2-19","revision":1,"level":"B2","levelIndex":4,"order":19,"title":"Word formation: so‘z oilalari","objective":"So‘zning vazifasiga ko‘ra noun, verb, adjective va adverb shaklini tanlaysiz.","context":"Word formation: so‘z oilalari","prerequisites":["en-b2-18"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Success noun, succeed verb, successful adjective, successfully adverb.","Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring.","Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless."],"pattern":"succeed → success → successful → successfully","examples":["The trial was successful.","The team completed it successfully.","Success depends on careful preparation.","They hope to succeed next time.","The instructions were useful.","The plan was impossible within one day."],"vocabulary":[{"id":"en-b2-19-v0","term":"successful","meaning":"muvaffaqiyatli","ipa":"/səkˈsesfəl/","collocation":"a successful trial","example":"The trial was successful."},{"id":"en-b2-19-v1","term":"successfully","meaning":"muvaffaqiyat bilan","ipa":"/səkˈsesfəli/","collocation":"complete successfully","example":"The team completed it successfully."},{"id":"en-b2-19-v2","term":"reliable","meaning":"ishonchli","ipa":"/rɪˈlaɪəbəl/","collocation":"reliable evidence","example":"The club report describes a successful trial, then claims that success proves the plan is reliable."},{"id":"en-b2-19-v3","term":"reliability","meaning":"ishonchlilik","ipa":"/rɪˌlaɪəˈbɪləti/","collocation":"check reliability","example":"The teacher asks what reliability means in this context."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["succeed → success → successful → successfully","The trial was successful.","The team completed it successfully."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The first trial succeeded.","A second group tested the same instructions.","Evaluate reliability across similar conditions."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"They hope to succeed next time.","audio":"/english-course/v7.23/en-b2-19-dictation.mp3"},"exercises":[{"id":"en-b2-19-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The trial was ___. (success)","answers":["successful"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","options":["successful","success","successfully"]},{"id":"en-b2-19-gap","type":"grammarFill","skill":"grammar","prompt":"The trial was ___. (success)","answers":["successful"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The trial was successful."],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","tokens":["The","trial","was","successful."]},{"id":"en-b2-19-fix","type":"correction","skill":"grammar","prompt":"The team worked successful.","answers":["The team worked successfully."],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["muvaffaqiyatli","muvaffaqiyat bilan","ishonchli","ishonchlilik"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"succeed → success → successful → successfully","left":["successful","successfully","reliable","reliability"],"options":["muvaffaqiyatli","muvaffaqiyat bilan","ishonchli","ishonchlilik"]},{"id":"en-b2-19-transform","type":"transformation","skill":"grammar","prompt":"Adverb bilan: Their work was successful.","answers":["They worked successfully."],"hint":"succeed → success → successful → successfully","explanation":"Success noun, succeed verb, successful adjective, successfully adverb."},{"id":"en-b2-19-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The first trial succeeded.","A second group tested the same instructions.","Evaluate reliability across similar conditions."],"answers":["The first trial succeeded.\nA second group tested the same instructions.\nEvaluate reliability across similar conditions."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The club report describes a successful trial, then claims that success proves the plan is reliable. The teacher asks what reliability means in this context. One positive event is evidence of success, but a reliable process should work consistently under similar conditions. The group repeats the trial with another class and checks whether the instructions can be followed without extra help. They also edit word forms. “The team worked successful” becomes “The team worked successfully.” Selecting the right suffix matters grammatically, while selecting the right concept matters logically. A word family can help express an idea precisely only when the writer understands the relation between the words. The revised report separates a successful event from evidence of reliability.","sentences":["The club report describes a successful trial, then claims that success proves the plan is reliable.","The teacher asks what reliability means in this context.","One positive event is evidence of success, but a reliable process should work consistently under similar conditions.","The group repeats the trial with another class and checks whether the instructions can be followed without extra help.","They also edit word forms.","“The team worked successful” becomes “The team worked successfully.","” Selecting the right suffix matters grammatically, while selecting the right concept matters logically.","A word family can help express an idea precisely only when the writer understands the relation between the words.","The revised report separates a successful event from evidence of reliability."],"questions":[{"id":"en-b2-19-reading0","type":"choice","skill":"reading","prompt":"Success nimani hali isbotlamaydi?","answers":["consistent reliability"],"explanation":"Bir muvaffaqiyat doimiylikni kafolatlamaydi.","hint":"succeed → success → successful → successfully","options":["consistent reliability","a positive event","that the trial occurred"]},{"id":"en-b2-19-reading1","type":"choice","skill":"reading","prompt":"Successfully qanday ishlaydi?","answers":["it describes how they worked"],"explanation":"Adverb fe’lga.","hint":"succeed → success → successful → successfully","options":["it describes how they worked","it names an event","it describes a noun only"]},{"id":"en-b2-19-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"succeed → success → successful → successfully","options":["The club report describes a successful trial, then claims that success proves the plan is reliable.","The teacher asks what reliability means in this context.","One positive event is evidence of success, but a reliable process should work consistently under similar conditions.","The group repeats the trial with another class and checks whether the instructions can be followed without extra help.","They also edit word forms.","“The team worked successful” becomes “The team worked successfully.","” Selecting the right suffix matters grammatically, while selecting the right concept matters logically.","A word family can help express an idea precisely only when the writer understands the relation between the words.","The revised report separates a successful event from evidence of reliability."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is reliability. The club report describes a successful trial, then claims that success proves the plan is reliable. The teacher asks what reliability means in this context. Speaker two: My main point is consistency. Reliability requires more than one successful event. The club report describes a successful trial, then claims that success proves the plan is reliable. The teacher asks what reliability means in this context. One positive event is evidence of success, but a reliable process should work consistently under similar conditions. The group repeats the trial with another class and checks whether the instructions can be followed without extra help. They also edit word forms. “The team worked successful” becomes “The team worked successfully.” Selecting the right suffix matters grammatically, while selecting the right concept matters logically. A word family can help express an idea precisely only when the writer understands the relation between the words. The revised report separates a successful event from evidence of reliability.","audio":"/english-course/v7.23/en-b2-19.mp3","synthetic":true,"questions":[{"id":"en-b2-19-listening0","type":"choice","skill":"listening","prompt":"Success nimani hali isbotlamaydi?","answers":["consistent reliability"],"explanation":"Bir muvaffaqiyat doimiylikni kafolatlamaydi.","hint":"succeed → success → successful → successfully","options":["consistent reliability","a positive event","that the trial occurred"]},{"id":"en-b2-19-listening1","type":"choice","skill":"listening","prompt":"Successfully qanday ishlaydi?","answers":["it describes how they worked"],"explanation":"Adverb fe’lga.","hint":"succeed → success → successful → successfully","options":["it describes how they worked","it names an event","it describes a noun only"]},{"id":"en-b2-19-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["reliability","consistency"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"succeed → success → successful → successfully","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-19-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["They hope to succeed next time."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"succeed → success → successful → successfully","audio":"/english-course/v7.23/en-b2-19-dictation.mp3","transcript":"They hope to succeed next time."}]},"writing":{"task":"Trial reportda word family va success/reliability farqini qo‘llang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The first trial was successful, and the team completed the task successfully. However, one success does not establish the reliability of the process. We repeated the activity with another class to see whether the instructions could be followed without extra help. The second group also completed the task, although it needed more time. We therefore have encouraging evidence of consistency, but we should continue checking the method under similar conditions. The report uses different word forms to describe the result, the action, and the quality being evaluated.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The trial was successful.","The team completed it successfully.","Success depends on careful preparation."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Trial reportda word family va success/reliability farqini qo‘llang. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Trial reportda word family va success/reliability farqini qo‘llang.","exit":[[{"id":"en-b2-19-exit0","type":"grammarFill","skill":"grammar","prompt":"The trial was ___. (success)","answers":["successful"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-exit1","type":"grammarFill","skill":"grammar","prompt":"They worked ___. (successful)","answers":["successfully"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-exit2","type":"grammarFill","skill":"grammar","prompt":"They hope to ___. (success)","answers":["succeed"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-exit3","type":"choice","skill":"grammar","prompt":"Success nimani hali isbotlamaydi?","answers":["consistent reliability"],"explanation":"Bir muvaffaqiyat doimiylikni kafolatlamaydi.","hint":"succeed → success → successful → successfully","options":["consistent reliability","a positive event","that the trial occurred"]},{"id":"en-b2-19-exit4","type":"choice","skill":"grammar","prompt":"Successfully qanday ishlaydi?","answers":["it describes how they worked"],"explanation":"Adverb fe’lga.","hint":"succeed → success → successful → successfully","options":["it describes how they worked","it names an event","it describes a noun only"]}],[{"id":"en-b2-19-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The team completed it successfully."],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","tokens":["The","team","completed","it","successfully."]},{"id":"en-b2-19-exit-b1","type":"grammarFill","skill":"grammar","prompt":"They worked ___. (successful)","answers":["successfully"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully"},{"id":"en-b2-19-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["They hope to succeed next time."],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","tokens":["They","hope","to","succeed","next","time."]},{"id":"en-b2-19-exit-b3","type":"choice","skill":"grammar","prompt":"Success nimani hali isbotlamaydi?","answers":["consistent reliability"],"explanation":"Bir muvaffaqiyat doimiylikni kafolatlamaydi.","hint":"succeed → success → successful → successfully","options":["consistent reliability","a positive event","that the trial occurred"]},{"id":"en-b2-19-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The plan was impossible within one day."],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","tokens":["The","plan","was","impossible","within","one","day."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-19","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-20','en-b2-20',null,4,20,'published',1,'{"id":"en-b2-20","baseId":"en-b2-20","revision":1,"level":"B2","levelIndex":4,"order":20,"title":"Collocations va phrasal verbs","objective":"Tabiiy birikmani vaziyat va so‘z tartibi bilan qo‘llaysiz.","context":"Collocations va phrasal verbs","prerequisites":["en-b2-19"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing.","Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq.","Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi."],"pattern":"raise concerns / carry out a survey / put it off","examples":["We raised a concern about access.","The team carried out a survey.","Do not draw a conclusion too early.","They put the meeting off.","We should not put it off again.","She brought up another option."],"vocabulary":[{"id":"en-b2-20-v0","term":"raise a concern","meaning":"tashvishni bildirmoq","ipa":"/reɪz ə kənˈsɜːn/","collocation":"raise a practical concern","example":"raise a practical concern"},{"id":"en-b2-20-v1","term":"carry out","meaning":"bajarmoq","ipa":"/ˈkæri aʊt/","collocation":"carry out a survey","example":"carry out a survey"},{"id":"en-b2-20-v2","term":"draw a conclusion","meaning":"xulosa chiqarmoq","ipa":"/drɔː ə kənˈkluːʒən/","collocation":"draw a cautious conclusion","example":"Do not draw a conclusion too early."},{"id":"en-b2-20-v3","term":"put off","meaning":"kechiktirmoq","ipa":"/pʊt ɒf/","collocation":"put it off","example":"put it off"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["raise concerns / carry out a survey / put it off","We raised a concern about access.","The team carried out a survey."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Repeated postponement may exclude members.","A survey will collect wider availability.","Wait for the full response period before deciding."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"They put the meeting off.","audio":"/english-course/v7.23/en-b2-20-dictation.mp3"},"exercises":[{"id":"en-b2-20-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: We ___ a concern yesterday. (raise)","answers":["raised"],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off","options":["raised","raising","raises"]},{"id":"en-b2-20-gap","type":"grammarFill","skill":"grammar","prompt":"We ___ a concern yesterday. (raise)","answers":["raised"],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off"},{"id":"en-b2-20-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We raised a concern about access."],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off","tokens":["We","raised","a","concern","about","access."]},{"id":"en-b2-20-fix","type":"correction","skill":"grammar","prompt":"Do not put off it again.","answers":["Do not put it off again."],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off"},{"id":"en-b2-20-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["tashvishni bildirmoq","bajarmoq","xulosa chiqarmoq","kechiktirmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"raise concerns / carry out a survey / put it off","left":["raise a concern","carry out","draw a conclusion","put off"],"options":["tashvishni bildirmoq","bajarmoq","xulosa chiqarmoq","kechiktirmoq"]},{"id":"en-b2-20-transform","type":"transformation","skill":"grammar","prompt":"Phrasal verb: They postponed the meeting.","answers":["They put the meeting off."],"hint":"raise concerns / carry out a survey / put it off","explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing."},{"id":"en-b2-20-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Repeated postponement may exclude members.","A survey will collect wider availability.","Wait for the full response period before deciding."],"answers":["Repeated postponement may exclude members.\nA survey will collect wider availability.\nWait for the full response period before deciding."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-20-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["We raised a concern about access."],"tokens":["We","raised","a","concern","about","access."],"hint":"raise concerns / carry out a survey / put it off","explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing."},{"id":"en-b2-20-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Odobli e’tiroz va hedging: Til vositasini tanlang: The result appears ___ support the plan.","answers":["to"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","options":["to","for","that"],"recap":true,"sourceLesson":"Odobli e’tiroz va hedging"},{"id":"en-b2-20-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Register: formal email va samimiy xabar: Til vositasini tanlang: Could you please ___ the deadline? (clarify)","answers":["clarify"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?","options":["clarify","clarifying","clarified"],"recap":true,"sourceLesson":"Register: formal email va samimiy xabar"},{"id":"en-b2-20-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Word formation: so‘z oilalari: Til vositasini tanlang: The trial was ___. (success)","answers":["successful"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","options":["successful","success","successfully"],"recap":true,"sourceLesson":"Word formation: so‘z oilalari"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The committee put the meeting off because several students could not attend. A member then raised a concern that repeated delays might exclude people with limited free time. Another suggested carrying out a short survey before choosing a date. The group agreed, but one student drew a conclusion from only the first two replies. The organiser asked everyone to wait until the response period ended. Useful collocations make the minutes sound natural, yet they do not guarantee a sensible decision. The committee needs both accurate language and a fair process. In the revised minutes, it records the concern, the evidence to be collected, and the date when a conclusion will be discussed. This gives readers more than a list of fluent phrases.","sentences":["The committee put the meeting off because several students could not attend.","A member then raised a concern that repeated delays might exclude people with limited free time.","Another suggested carrying out a short survey before choosing a date.","The group agreed, but one student drew a conclusion from only the first two replies.","The organiser asked everyone to wait until the response period ended.","Useful collocations make the minutes sound natural, yet they do not guarantee a sensible decision.","The committee needs both accurate language and a fair process.","In the revised minutes, it records the concern, the evidence to be collected, and the date when a conclusion will be discussed.","This gives readers more than a list of fluent phrases."],"questions":[{"id":"en-b2-20-reading0","type":"choice","skill":"reading","prompt":"Nega first two replies yetarli emas?","answers":["the response period had not ended"],"explanation":"Tanlov hali tugamagan.","hint":"raise concerns / carry out a survey / put it off","options":["the response period had not ended","all surveys are useless","there were no replies"]},{"id":"en-b2-20-reading1","type":"choice","skill":"reading","prompt":"Minutes nima ko‘rsatishi kerak?","answers":["concern, evidence, and decision date"],"explanation":"Jarayon qayd etiladi.","hint":"raise concerns / carry out a survey / put it off","options":["concern, evidence, and decision date","only fluent phrases","only the earliest replies"]},{"id":"en-b2-20-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"raise concerns / carry out a survey / put it off","options":["The committee put the meeting off because several students could not attend.","A member then raised a concern that repeated delays might exclude people with limited free time.","Another suggested carrying out a short survey before choosing a date.","The group agreed, but one student drew a conclusion from only the first two replies.","The organiser asked everyone to wait until the response period ended.","Useful collocations make the minutes sound natural, yet they do not guarantee a sensible decision.","The committee needs both accurate language and a fair process.","In the revised minutes, it records the concern, the evidence to be collected, and the date when a conclusion will be discussed.","This gives readers more than a list of fluent phrases."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is survey. The committee put the meeting off because several students could not attend. A member then raised a concern that repeated delays might exclude people with limited free time. Speaker two: My main point is fairness. Natural phrasing should describe a fair process, not replace it. The committee put the meeting off because several students could not attend. A member then raised a concern that repeated delays might exclude people with limited free time. Another suggested carrying out a short survey before choosing a date. The group agreed, but one student drew a conclusion from only the first two replies. The organiser asked everyone to wait until the response period ended. Useful collocations make the minutes sound natural, yet they do not guarantee a sensible decision. The committee needs both accurate language and a fair process. In the revised minutes, it records the concern, the evidence to be collected, and the date when a conclusion will be discussed. This gives readers more than a list of fluent phrases.","audio":"/english-course/v7.23/en-b2-20.mp3","synthetic":true,"questions":[{"id":"en-b2-20-listening0","type":"choice","skill":"listening","prompt":"Nega first two replies yetarli emas?","answers":["the response period had not ended"],"explanation":"Tanlov hali tugamagan.","hint":"raise concerns / carry out a survey / put it off","options":["the response period had not ended","all surveys are useless","there were no replies"]},{"id":"en-b2-20-listening1","type":"choice","skill":"listening","prompt":"Minutes nima ko‘rsatishi kerak?","answers":["concern, evidence, and decision date"],"explanation":"Jarayon qayd etiladi.","hint":"raise concerns / carry out a survey / put it off","options":["concern, evidence, and decision date","only fluent phrases","only the earliest replies"]},{"id":"en-b2-20-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["survey","fairness"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"raise concerns / carry out a survey / put it off","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-20-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["They put the meeting off."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"raise concerns / carry out a survey / put it off","audio":"/english-course/v7.23/en-b2-20-dictation.mp3","transcript":"They put the meeting off."}]},"writing":{"task":"Committee minutes: tashvish, survey, muddat va ehtiyotkor xulosa yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The committee raised a concern about repeated delays to the meeting. Some members have limited free time, so postponement may reduce their chance to participate. We agreed to carry out a short survey before choosing a new date. The response period will remain open until Friday, and we should not draw a conclusion from the earliest replies alone. At the next meeting, we will compare the full set of responses and explain how the chosen date balances different needs. These minutes record both the concern and the decision process.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["We raised a concern about access.","The team carried out a survey.","Do not draw a conclusion too early."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Committee minutes: tashvish, survey, muddat va ehtiyotkor xulosa yozing. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Committee minutes: tashvish, survey, muddat va ehtiyotkor xulosa yozing.","exit":[[{"id":"en-b2-20-exit0","type":"grammarFill","skill":"grammar","prompt":"We ___ a concern yesterday. (raise)","answers":["raised"],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off"},{"id":"en-b2-20-exit1","type":"grammarFill","skill":"grammar","prompt":"They carried ___ a survey.","answers":["out"],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off"},{"id":"en-b2-20-exit2","type":"grammarFill","skill":"grammar","prompt":"Do not put ___ off. (it)","answers":["it"],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off"},{"id":"en-b2-20-exit3","type":"choice","skill":"grammar","prompt":"Nega first two replies yetarli emas?","answers":["the response period had not ended"],"explanation":"Tanlov hali tugamagan.","hint":"raise concerns / carry out a survey / put it off","options":["the response period had not ended","all surveys are useless","there were no replies"]},{"id":"en-b2-20-exit4","type":"choice","skill":"grammar","prompt":"Minutes nima ko‘rsatishi kerak?","answers":["concern, evidence, and decision date"],"explanation":"Jarayon qayd etiladi.","hint":"raise concerns / carry out a survey / put it off","options":["concern, evidence, and decision date","only fluent phrases","only the earliest replies"]}],[{"id":"en-b2-20-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The team carried out a survey."],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off","tokens":["The","team","carried","out","a","survey."]},{"id":"en-b2-20-exit-b1","type":"grammarFill","skill":"grammar","prompt":"They carried ___ a survey.","answers":["out"],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off"},{"id":"en-b2-20-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["They put the meeting off."],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off","tokens":["They","put","the","meeting","off."]},{"id":"en-b2-20-exit-b3","type":"choice","skill":"grammar","prompt":"Nega first two replies yetarli emas?","answers":["the response period had not ended"],"explanation":"Tanlov hali tugamagan.","hint":"raise concerns / carry out a survey / put it off","options":["the response period had not ended","all surveys are useless","there were no replies"]},{"id":"en-b2-20-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She brought up another option."],"explanation":"Draw a conclusion, raise a concern, carry out a survey kabi birikmalarni kontekstda o‘rganing. Put off — kechiktirmoq; carry out — bajarmoq; bring up — muhokamaga ko‘tarmoq. Ajraladigan fe’lda olmosh o‘rtada: put it off; birikmani yodlash ma’noni tushunish o‘rnini bosmaydi.","hint":"raise concerns / carry out a survey / put it off","tokens":["She","brought","up","another","option."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-b2-20-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Odobli e’tiroz va hedging: Til vositasini tanlang: The result appears ___ support the plan.","answers":["to"],"explanation":"May/might, tends to, appears to xulosa kuchini chegaralaydi. I see your point, but … kelishilgan qismdan e’tirozga o‘tadi. Hedging dalilsiz fikrni isbotlamaydi; juda ko‘p yumshatish ham ma’noni noaniq qilishi mumkin.","hint":"appears to / may suggest / I see your point, but","options":["to","for","that"],"recap":true,"sourceLesson":"Odobli e’tiroz va hedging"},{"id":"en-b2-20-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Register: formal email va samimiy xabar: Til vositasini tanlang: Could you please ___ the deadline? (clarify)","answers":["clarify"],"explanation":"Formal register aniq maqsad, hurmatli murojaat va mos so‘rov; murakkab so‘z shart emas. Could you please … va I would appreciate … so‘rovni yumshatadi. Informal qisqartma do‘stga mos; rasmiy xabarda haqorat yoki haddan tashqari talab ohangidan saqlaning.","hint":"Could you please clarify …? / Can you tell me …?","options":["clarify","clarifying","clarified"],"recap":true,"sourceLesson":"Register: formal email va samimiy xabar"},{"id":"en-b2-20-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Word formation: so‘z oilalari: Til vositasini tanlang: The trial was ___. (success)","answers":["successful"],"explanation":"Success noun, succeed verb, successful adjective, successfully adverb. Prefix/suffix ma’no va so‘z turini o‘zgartirishi mumkin; har yangi shaklni lug‘atda tekshiring. Negative prefixlar hamma so‘zga bir xil qo‘shilmaydi: possible/impossible, useful/useless.","hint":"succeed → success → successful → successfully","options":["successful","success","successfully"],"recap":true,"sourceLesson":"Word formation: so‘z oilalari"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-21','en-b2-21',null,4,21,'published',1,'{"id":"en-b2-21","baseId":"en-b2-21","revision":1,"level":"B2","levelIndex":4,"order":21,"title":"Opinion essay: dalil va qarshi fikr","objective":"Fikrni ikki dalil va adolatli counterargument bilan tuzasiz.","context":"Opinion essay: dalil va qarshi fikr","prerequisites":["en-b2-20"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi.","Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang.","Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering."],"pattern":"claim → evidence → explanation → counterargument → conclusion","examples":["I support a limited trial rather than an immediate change.","One reason is that the current evidence is incomplete.","For example, only volunteers answered.","Critics reasonably point out the cost.","However, a short trial can limit that cost.","The decision should follow the trial results."],"vocabulary":[{"id":"en-b2-21-v0","term":"claim","meaning":"da’vo","ipa":"/kleɪm/","collocation":"support a claim","example":"support a claim"},{"id":"en-b2-21-v1","term":"counterargument","meaning":"qarshi dalil","ipa":"/ˈkaʊntəˌɑːɡjʊmənt/","collocation":"address a counterargument","example":"address a counterargument"},{"id":"en-b2-21-v2","term":"justify","meaning":"asoslamoq","ipa":"/ˈdʒʌstɪfaɪ/","collocation":"justify a recommendation","example":"justify a recommendation"},{"id":"en-b2-21-v3","term":"representative","meaning":"vakillik qiluvchi","ipa":"/ˌreprɪˈzentətɪv/","collocation":"a representative sample","example":"a representative sample"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["claim → evidence → explanation → counterargument → conclusion","I support a limited trial rather than an immediate change.","One reason is that the current evidence is incomplete."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Access is more important than the medium.","Some families do not check the app.","Use a mixed trial to test reliable delivery."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Critics reasonably point out the cost.","audio":"/english-course/v7.23/en-b2-21-dictation.mp3"},"exercises":[{"id":"en-b2-21-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Critics reasonably ___ out the cost. (point)","answers":["point"],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["point","points","pointing"]},{"id":"en-b2-21-gap","type":"grammarFill","skill":"grammar","prompt":"Critics reasonably ___ out the cost. (point)","answers":["point"],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion"},{"id":"en-b2-21-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I support a limited trial rather than an immediate change."],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion","tokens":["I","support","a","limited","trial","rather","than","an","immediate","change."]},{"id":"en-b2-21-fix","type":"correction","skill":"grammar","prompt":"Critics dislike technology, so their access concern is irrelevant.","answers":["Critics raise an access concern that the plan should address."],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion"},{"id":"en-b2-21-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["da’vo","qarshi dalil","asoslamoq","vakillik qiluvchi"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"claim → evidence → explanation → counterargument → conclusion","left":["claim","counterargument","justify","representative"],"options":["da’vo","qarshi dalil","asoslamoq","vakillik qiluvchi"]},{"id":"en-b2-21-transform","type":"transformation","skill":"grammar","prompt":"Counterargumentni tan oling: Some families do not use the app.","answers":["Critics reasonably point out that some families do not use the app."],"hint":"claim → evidence → explanation → counterargument → conclusion","explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi."},{"id":"en-b2-21-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Access is more important than the medium.","Some families do not check the app.","Use a mixed trial to test reliable delivery."],"answers":["Access is more important than the medium.\nSome families do not check the app.\nUse a mixed trial to test reliable delivery."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-21-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["claim","counterargument","justify","representative"],"options":["support a claim","address a counterargument","justify a recommendation","a representative sample"],"answers":["support a claim","address a counterargument","justify a recommendation","a representative sample"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Should the school replace every printed notice with an online message? Supporters say updates would reach readers quickly and reduce wasted paper. Critics point out that not every family checks the same app. A student essay initially describes critics as people who dislike technology. That weak version of their argument is easy to dismiss but does not address the access problem. The writer revises the essay to acknowledge the strongest objection and proposes a mixed trial: online messages plus one shared printed board. The trial would measure whether families receive important information on time. A persuasive essay should not merely defeat an imagined opponent. It should help readers compare realistic options and understand why a recommendation follows from the evidence.","sentences":["Should the school replace every printed notice with an online message?","Supporters say updates would reach readers quickly and reduce wasted paper.","Critics point out that not every family checks the same app.","A student essay initially describes critics as people who dislike technology.","That weak version of their argument is easy to dismiss but does not address the access problem.","The writer revises the essay to acknowledge the strongest objection and proposes a mixed trial: online messages plus one shared printed board.","The trial would measure whether families receive important information on time.","A persuasive essay should not merely defeat an imagined opponent.","It should help readers compare realistic options and understand why a recommendation follows from the evidence."],"questions":[{"id":"en-b2-21-reading0","type":"choice","skill":"reading","prompt":"Criticsning asosiy dalili?","answers":["unequal access to the app"],"explanation":"Hamma bir appni tekshirmaydi.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["unequal access to the app","hatred of every technology","paper never costs money"]},{"id":"en-b2-21-reading1","type":"choice","skill":"reading","prompt":"Revised essay kuchi nima?","answers":["it answers the strongest real objection"],"explanation":"Accessga amaliy mixed yechim.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["it answers the strongest real objection","it ignores critics","it invents survey results"]},{"id":"en-b2-21-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["Should the school replace every printed notice with an online message?","Supporters say updates would reach readers quickly and reduce wasted paper.","Critics point out that not every family checks the same app.","A student essay initially describes critics as people who dislike technology.","That weak version of their argument is easy to dismiss but does not address the access problem.","The writer revises the essay to acknowledge the strongest objection and proposes a mixed trial: online messages plus one shared printed board.","The trial would measure whether families receive important information on time.","A persuasive essay should not merely defeat an imagined opponent.","It should help readers compare realistic options and understand why a recommendation follows from the evidence."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is access. Should the school replace every printed notice with an online message? Supporters say updates would reach readers quickly and reduce wasted paper. Speaker two: My main point is trial. Test a mixed approach before removing the printed board. Should the school replace every printed notice with an online message? Supporters say updates would reach readers quickly and reduce wasted paper. Critics point out that not every family checks the same app. A student essay initially describes critics as people who dislike technology. That weak version of their argument is easy to dismiss but does not address the access problem. The writer revises the essay to acknowledge the strongest objection and proposes a mixed trial: online messages plus one shared printed board. The trial would measure whether families receive important information on time. A persuasive essay should not merely defeat an imagined opponent. It should help readers compare realistic options and understand why a recommendation follows from the evidence.","audio":"/english-course/v7.23/en-b2-21.mp3","synthetic":true,"questions":[{"id":"en-b2-21-listening0","type":"choice","skill":"listening","prompt":"Criticsning asosiy dalili?","answers":["unequal access to the app"],"explanation":"Hamma bir appni tekshirmaydi.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["unequal access to the app","hatred of every technology","paper never costs money"]},{"id":"en-b2-21-listening1","type":"choice","skill":"listening","prompt":"Revised essay kuchi nima?","answers":["it answers the strongest real objection"],"explanation":"Accessga amaliy mixed yechim.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["it answers the strongest real objection","it ignores critics","it invents survey results"]},{"id":"en-b2-21-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["access","trial"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"claim → evidence → explanation → counterargument → conclusion","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-21-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Critics reasonably point out the cost."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"claim → evidence → explanation → counterargument → conclusion","audio":"/english-course/v7.23/en-b2-21-dictation.mp3","transcript":"Critics reasonably point out the cost."}]},"writing":{"task":"Online va printed notice haqida opinion essay: ikki dalil, real counterargument va tavsiya.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"I support testing online notices while keeping one shared printed board. Online messages can be updated quickly, which helps when an event changes at short notice. However, critics reasonably point out that some families do not check the same app. Removing every printed notice would therefore risk excluding them. A mixed trial could measure how reliably important information reaches families through each method. The aim should be timely access, rather than proving that one medium is always better. If the trial shows that online messages reach everyone, the school can reconsider the printed board with stronger evidence.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["I support a limited trial rather than an immediate change.","One reason is that the current evidence is incomplete.","For example, only volunteers answered."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Online va printed notice haqida opinion essay: ikki dalil, real counterargument va tavsiya. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Online va printed notice haqida opinion essay: ikki dalil, real counterargument va tavsiya.","exit":[[{"id":"en-b2-21-exit0","type":"grammarFill","skill":"grammar","prompt":"Critics reasonably ___ out the cost. (point)","answers":["point"],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion"},{"id":"en-b2-21-exit1","type":"grammarFill","skill":"grammar","prompt":"A trial can ___ that cost. (limit)","answers":["limit"],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion"},{"id":"en-b2-21-exit2","type":"grammarFill","skill":"grammar","prompt":"The decision should ___ the results. (follow)","answers":["follow"],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion"},{"id":"en-b2-21-exit3","type":"choice","skill":"grammar","prompt":"Criticsning asosiy dalili?","answers":["unequal access to the app"],"explanation":"Hamma bir appni tekshirmaydi.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["unequal access to the app","hatred of every technology","paper never costs money"]},{"id":"en-b2-21-exit4","type":"choice","skill":"grammar","prompt":"Revised essay kuchi nima?","answers":["it answers the strongest real objection"],"explanation":"Accessga amaliy mixed yechim.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["it answers the strongest real objection","it ignores critics","it invents survey results"]}],[{"id":"en-b2-21-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["One reason is that the current evidence is incomplete."],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion","tokens":["One","reason","is","that","the","current","evidence","is","incomplete."]},{"id":"en-b2-21-exit-b1","type":"grammarFill","skill":"grammar","prompt":"A trial can ___ that cost. (limit)","answers":["limit"],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion"},{"id":"en-b2-21-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Critics reasonably point out the cost."],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion","tokens":["Critics","reasonably","point","out","the","cost."]},{"id":"en-b2-21-exit-b3","type":"choice","skill":"grammar","prompt":"Criticsning asosiy dalili?","answers":["unequal access to the app"],"explanation":"Hamma bir appni tekshirmaydi.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["unequal access to the app","hatred of every technology","paper never costs money"]},{"id":"en-b2-21-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The decision should follow the trial results."],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion","tokens":["The","decision","should","follow","the","trial","results."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-22','en-b2-22',null,4,22,'published',1,'{"id":"en-b2-22","baseId":"en-b2-22","revision":1,"level":"B2","levelIndex":4,"order":22,"title":"Report va review: maqsad farqi","objective":"Hisobotdagi kuzatuvni reviewdagi bahodan ajratasiz.","context":"Report va review: maqsad farqi","prerequisites":["en-b2-21"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho.","Baho subyektiv bo‘lsa uning mezonini ochiq ayting.","Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak."],"pattern":"findings → recommendation / experience → evaluation","examples":["The report records attendance at each session.","The review evaluates the quality of the guide.","Most visitors found the labels clear.","The survey did not include evening visitors.","I would recommend the tour to first-time visitors.","The recommendation is limited to the evidence collected."],"vocabulary":[{"id":"en-b2-22-v0","term":"finding","meaning":"aniqlangan natija","ipa":"/ˈfaɪndɪŋ/","collocation":"report findings","example":"The report notes that the survey excluded evening visitors, so its findings are incomplete."},{"id":"en-b2-22-v1","term":"criterion","meaning":"mezon","ipa":"/kraɪˈtɪəriən/","collocation":"an evaluation criterion","example":"an evaluation criterion"},{"id":"en-b2-22-v2","term":"evaluate","meaning":"baholamoq","ipa":"/ɪˈvæljueɪt/","collocation":"evaluate a guide","example":"The review evaluates the quality of the guide."},{"id":"en-b2-22-v3","term":"recommendation","meaning":"tavsiya","ipa":"/ˌrekəmenˈdeɪʃən/","collocation":"a supported recommendation","example":"The recommendation is limited to the evidence collected."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["findings → recommendation / experience → evaluation","The report records attendance at each session.","The review evaluates the quality of the guide."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The texts answer different questions.","Facts and evaluation share one experience.","State the criteria and limits of the recommendation."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The survey did not include evening visitors.","audio":"/english-course/v7.23/en-b2-22-dictation.mp3"},"exercises":[{"id":"en-b2-22-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The review ___ the guide. (evaluate)","answers":["evaluates"],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation","options":["evaluates","evaluate","evaluating"]},{"id":"en-b2-22-gap","type":"grammarFill","skill":"grammar","prompt":"The review ___ the guide. (evaluate)","answers":["evaluates"],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation"},{"id":"en-b2-22-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The report records attendance at each session."],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation","tokens":["The","report","records","attendance","at","each","session."]},{"id":"en-b2-22-fix","type":"correction","skill":"grammar","prompt":"Every visitor will like it because I liked it.","answers":["I recommend it to first-time visitors because the explanations were clear."],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation"},{"id":"en-b2-22-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["aniqlangan natija","mezon","baholamoq","tavsiya"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"findings → recommendation / experience → evaluation","left":["finding","criterion","evaluate","recommendation"],"options":["aniqlangan natija","mezon","baholamoq","tavsiya"]},{"id":"en-b2-22-transform","type":"transformation","skill":"grammar","prompt":"Mezonga bog‘lang: The tour was good.","answers":["The tour was useful for first-time visitors because the explanations were clear."],"hint":"findings → recommendation / experience → evaluation","explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho."},{"id":"en-b2-22-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The texts answer different questions.","Facts and evaluation share one experience.","State the criteria and limits of the recommendation."],"answers":["The texts answer different questions.\nFacts and evaluation share one experience.\nState the criteria and limits of the recommendation."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"After a museum visit, the class writes two texts. The report records attendance and survey results for the organiser. The review helps future visitors decide whether the tour suits them. Both use the same experience, but they answer different questions. The report notes that the survey excluded evening visitors, so its findings are incomplete. The review explains that the guide’s clear explanations were useful for first-time visitors, although experienced visitors might want more detail. Neither text needs to pretend to be completely objective. It needs to show where facts end and evaluation begins. A recommendation becomes more useful when the reader knows the criteria and the audience for whom it was made.","sentences":["After a museum visit, the class writes two texts.","The report records attendance and survey results for the organiser.","The review helps future visitors decide whether the tour suits them.","Both use the same experience, but they answer different questions.","The report notes that the survey excluded evening visitors, so its findings are incomplete.","The review explains that the guide’s clear explanations were useful for first-time visitors, although experienced visitors might want more detail.","Neither text needs to pretend to be completely objective.","It needs to show where facts end and evaluation begins.","A recommendation becomes more useful when the reader knows the criteria and the audience for whom it was made."],"questions":[{"id":"en-b2-22-reading0","type":"choice","skill":"reading","prompt":"Report kimga ma’lumot beradi?","answers":["the organiser"],"explanation":"Tashkilotchi natijalar uchun.","hint":"findings → recommendation / experience → evaluation","options":["the organiser","only future tourists","nobody"]},{"id":"en-b2-22-reading1","type":"choice","skill":"reading","prompt":"Review nima bilan chegaralanadi?","answers":["the needs of its audience"],"explanation":"Birinchi marta keluvchilar uchun mos.","hint":"findings → recommendation / experience → evaluation","options":["the needs of its audience","word count alone","all visitors are identical"]},{"id":"en-b2-22-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"findings → recommendation / experience → evaluation","options":["After a museum visit, the class writes two texts.","The report records attendance and survey results for the organiser.","The review helps future visitors decide whether the tour suits them.","Both use the same experience, but they answer different questions.","The report notes that the survey excluded evening visitors, so its findings are incomplete.","The review explains that the guide’s clear explanations were useful for first-time visitors, although experienced visitors might want more detail.","Neither text needs to pretend to be completely objective.","It needs to show where facts end and evaluation begins.","A recommendation becomes more useful when the reader knows the criteria and the audience for whom it was made."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is criterion. After a museum visit, the class writes two texts. The report records attendance and survey results for the organiser. Speaker two: My main point is audience. A recommendation is useful when readers know whom it suits. After a museum visit, the class writes two texts. The report records attendance and survey results for the organiser. The review helps future visitors decide whether the tour suits them. Both use the same experience, but they answer different questions. The report notes that the survey excluded evening visitors, so its findings are incomplete. The review explains that the guide’s clear explanations were useful for first-time visitors, although experienced visitors might want more detail. Neither text needs to pretend to be completely objective. It needs to show where facts end and evaluation begins. A recommendation becomes more useful when the reader knows the criteria and the audience for whom it was made.","audio":"/english-course/v7.23/en-b2-22.mp3","synthetic":true,"questions":[{"id":"en-b2-22-listening0","type":"choice","skill":"listening","prompt":"Report kimga ma’lumot beradi?","answers":["the organiser"],"explanation":"Tashkilotchi natijalar uchun.","hint":"findings → recommendation / experience → evaluation","options":["the organiser","only future tourists","nobody"]},{"id":"en-b2-22-listening1","type":"choice","skill":"listening","prompt":"Review nima bilan chegaralanadi?","answers":["the needs of its audience"],"explanation":"Birinchi marta keluvchilar uchun mos.","hint":"findings → recommendation / experience → evaluation","options":["the needs of its audience","word count alone","all visitors are identical"]},{"id":"en-b2-22-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["criterion","audience"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"findings → recommendation / experience → evaluation","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-22-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The survey did not include evening visitors."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"findings → recommendation / experience → evaluation","audio":"/english-course/v7.23/en-b2-22-dictation.mp3","transcript":"The survey did not include evening visitors."}]},"writing":{"task":"Bitta tashrif bo‘yicha qisqa report va review yozing; mezon va audience ni farqlang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The tour is a useful introduction for first-time visitors. The guide explains unfamiliar objects clearly and allows time for questions. I particularly valued the labels, which made it easy to return to an exhibit independently. However, visitors who already know the collection may want more detailed discussion. My recommendation is based on clarity and accessibility, rather than specialist depth. A separate attendance report should include the survey limitation: evening visitors were not asked for feedback. That limitation does not cancel the positive experience, but it narrows the claim we can make about all visitors.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The report records attendance at each session.","The review evaluates the quality of the guide.","Most visitors found the labels clear."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Bitta tashrif bo‘yicha qisqa report va review yozing; mezon va audience ni farqlang. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Bitta tashrif bo‘yicha qisqa report va review yozing; mezon va audience ni farqlang.","exit":[[{"id":"en-b2-22-exit0","type":"grammarFill","skill":"grammar","prompt":"The review ___ the guide. (evaluate)","answers":["evaluates"],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation"},{"id":"en-b2-22-exit1","type":"grammarFill","skill":"grammar","prompt":"Most visitors ___ the labels clear. (find, past)","answers":["found"],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation"},{"id":"en-b2-22-exit2","type":"grammarFill","skill":"grammar","prompt":"The survey did not ___ evening visitors. (include)","answers":["include"],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation"},{"id":"en-b2-22-exit3","type":"choice","skill":"grammar","prompt":"Report kimga ma’lumot beradi?","answers":["the organiser"],"explanation":"Tashkilotchi natijalar uchun.","hint":"findings → recommendation / experience → evaluation","options":["the organiser","only future tourists","nobody"]},{"id":"en-b2-22-exit4","type":"choice","skill":"grammar","prompt":"Review nima bilan chegaralanadi?","answers":["the needs of its audience"],"explanation":"Birinchi marta keluvchilar uchun mos.","hint":"findings → recommendation / experience → evaluation","options":["the needs of its audience","word count alone","all visitors are identical"]}],[{"id":"en-b2-22-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The review evaluates the quality of the guide."],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation","tokens":["The","review","evaluates","the","quality","of","the","guide."]},{"id":"en-b2-22-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Most visitors ___ the labels clear. (find, past)","answers":["found"],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation"},{"id":"en-b2-22-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The survey did not include evening visitors."],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation","tokens":["The","survey","did","not","include","evening","visitors."]},{"id":"en-b2-22-exit-b3","type":"choice","skill":"grammar","prompt":"Report kimga ma’lumot beradi?","answers":["the organiser"],"explanation":"Tashkilotchi natijalar uchun.","hint":"findings → recommendation / experience → evaluation","options":["the organiser","only future tourists","nobody"]},{"id":"en-b2-22-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The recommendation is limited to the evidence collected."],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation","tokens":["The","recommendation","is","limited","to","the","evidence","collected."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-23','en-b2-23',null,4,23,'published',1,'{"id":"en-b2-23","baseId":"en-b2-23","revision":1,"level":"B2","levelIndex":4,"order":23,"title":"Formal complaint va request","objective":"Muammo, ta’sir va aniq yechimni dalil bilan so‘raysiz.","context":"Formal complaint va request","prerequisites":["en-b2-22"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi.","I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin.","Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang."],"pattern":"problem → impact → evidence → requested action","examples":["I am writing about our booking.","The room was not available at the agreed time.","This delayed our meeting by thirty minutes.","The confirmation email gives a start time of ten.","Could you explain what caused the delay?","I would appreciate a clear response by Friday."],"vocabulary":[{"id":"en-b2-23-v0","term":"confirmation","meaning":"tasdiq xabari","ipa":"/ˌkɒnfəˈmeɪʃən/","collocation":"booking confirmation","example":"The confirmation email gives a start time of ten."},{"id":"en-b2-23-v1","term":"impact","meaning":"ta’sir","ipa":"/ˈɪmpækt/","collocation":"describe the impact","example":"describe the impact"},{"id":"en-b2-23-v2","term":"resolution","meaning":"yechim","ipa":"/ˌrezəˈluːʃən/","collocation":"seek a resolution","example":"seek a resolution"},{"id":"en-b2-23-v3","term":"correspondence","meaning":"yozishma","ipa":"/ˌkɒrɪˈspɒndəns/","collocation":"professional correspondence","example":"Professional correspondence can express dissatisfaction without guessing someone’s motives."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["problem → impact → evidence → requested action","I am writing about our booking.","The room was not available at the agreed time."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["A confirmed start time was missed.","The delay reduced discussion time.","Request an explanation and a practical prevention plan."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The confirmation email gives a start time of ten.","audio":"/english-course/v7.23/en-b2-23-dictation.mp3"},"exercises":[{"id":"en-b2-23-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: I am writing ___ our booking.","answers":["about"],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action","options":["about","at","of"]},{"id":"en-b2-23-gap","type":"grammarFill","skill":"grammar","prompt":"I am writing ___ our booking.","answers":["about"],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action"},{"id":"en-b2-23-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I am writing about our booking."],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action","tokens":["I","am","writing","about","our","booking."]},{"id":"en-b2-23-fix","type":"correction","skill":"grammar","prompt":"You are dishonest because our room was late.","answers":["The room was not available at the confirmed time, which delayed our meeting."],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action"},{"id":"en-b2-23-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["tasdiq xabari","ta’sir","yechim","yozishma"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"problem → impact → evidence → requested action","left":["confirmation","impact","resolution","correspondence"],"options":["tasdiq xabari","ta’sir","yechim","yozishma"]},{"id":"en-b2-23-transform","type":"transformation","skill":"grammar","prompt":"Hurmatli request: Explain the delay.","answers":["Could you explain what caused the delay?"],"hint":"problem → impact → evidence → requested action","explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi."},{"id":"en-b2-23-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["A confirmed start time was missed.","The delay reduced discussion time.","Request an explanation and a practical prevention plan."],"answers":["A confirmed start time was missed.\nThe delay reduced discussion time.\nRequest an explanation and a practical prevention plan."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A club booking email confirms that the room will be available at ten. On the day, another group is still using it, and the club waits thirty minutes. The first complaint calls the venue dishonest. The writer cannot support that intention claim, so she revises it to state the observable problem and its effect. She attaches the confirmation and asks for an explanation and a practical solution for the next booking. The revised message is firm but respectful. It does not weaken the complaint; it makes the requested response easier to identify. Professional correspondence can express dissatisfaction without guessing someone’s motives. The most useful outcome is a clear arrangement that prevents the same delay, not simply a stronger adjective.","sentences":["A club booking email confirms that the room will be available at ten.","On the day, another group is still using it, and the club waits thirty minutes.","The first complaint calls the venue dishonest.","The writer cannot support that intention claim, so she revises it to state the observable problem and its effect.","She attaches the confirmation and asks for an explanation and a practical solution for the next booking.","The revised message is firm but respectful.","It does not weaken the complaint; it makes the requested response easier to identify.","Professional correspondence can express dissatisfaction without guessing someone’s motives.","The most useful outcome is a clear arrangement that prevents the same delay, not simply a stronger adjective."],"questions":[{"id":"en-b2-23-reading0","type":"choice","skill":"reading","prompt":"Intention claim nega o‘zgartirildi?","answers":["dishonesty was not supported by evidence"],"explanation":"Motiv dalili yo‘q.","hint":"problem → impact → evidence → requested action","options":["dishonesty was not supported by evidence","there was no delay","politeness forbids complaints"]},{"id":"en-b2-23-reading1","type":"choice","skill":"reading","prompt":"Revised complaint maqsadi?","answers":["a practical solution and explanation"],"explanation":"Keyingi booking aniqligi.","hint":"problem → impact → evidence → requested action","options":["a practical solution and explanation","stronger insults","hide the confirmation"]},{"id":"en-b2-23-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"problem → impact → evidence → requested action","options":["A club booking email confirms that the room will be available at ten.","On the day, another group is still using it, and the club waits thirty minutes.","The first complaint calls the venue dishonest.","The writer cannot support that intention claim, so she revises it to state the observable problem and its effect.","She attaches the confirmation and asks for an explanation and a practical solution for the next booking.","The revised message is firm but respectful.","It does not weaken the complaint; it makes the requested response easier to identify.","Professional correspondence can express dissatisfaction without guessing someone’s motives.","The most useful outcome is a clear arrangement that prevents the same delay, not simply a stronger adjective."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is confirmation. A club booking email confirms that the room will be available at ten. On the day, another group is still using it, and the club waits thirty minutes. Speaker two: My main point is resolution. A firm complaint should ask for a practical resolution. A club booking email confirms that the room will be available at ten. On the day, another group is still using it, and the club waits thirty minutes. The first complaint calls the venue dishonest. The writer cannot support that intention claim, so she revises it to state the observable problem and its effect. She attaches the confirmation and asks for an explanation and a practical solution for the next booking. The revised message is firm but respectful. It does not weaken the complaint; it makes the requested response easier to identify. Professional correspondence can express dissatisfaction without guessing someone’s motives. The most useful outcome is a clear arrangement that prevents the same delay, not simply a stronger adjective.","audio":"/english-course/v7.23/en-b2-23.mp3","synthetic":true,"questions":[{"id":"en-b2-23-listening0","type":"choice","skill":"listening","prompt":"Intention claim nega o‘zgartirildi?","answers":["dishonesty was not supported by evidence"],"explanation":"Motiv dalili yo‘q.","hint":"problem → impact → evidence → requested action","options":["dishonesty was not supported by evidence","there was no delay","politeness forbids complaints"]},{"id":"en-b2-23-listening1","type":"choice","skill":"listening","prompt":"Revised complaint maqsadi?","answers":["a practical solution and explanation"],"explanation":"Keyingi booking aniqligi.","hint":"problem → impact → evidence → requested action","options":["a practical solution and explanation","stronger insults","hide the confirmation"]},{"id":"en-b2-23-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["confirmation","resolution"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"problem → impact → evidence → requested action","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-23-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The confirmation email gives a start time of ten."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"problem → impact → evidence → requested action","audio":"/english-course/v7.23/en-b2-23-dictation.mp3","transcript":"The confirmation email gives a start time of ten."}]},"writing":{"task":"Booking complaint email: tekshiriladigan fakt, ta’sir, dalil va so‘ralgan yechim.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Dear venue manager, I am writing about our booking for Tuesday at ten. The confirmation email gives that start time, but the room remained occupied until ten thirty. This delayed our meeting and reduced the time available for discussion. I have attached the confirmation for reference. Could you explain what caused the delay and confirm how the next booking will be protected from a similar problem? I would appreciate a clear response by Friday so that our group can plan its next session. Thank you for reviewing the matter.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["I am writing about our booking.","The room was not available at the agreed time.","This delayed our meeting by thirty minutes."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Booking complaint email: tekshiriladigan fakt, ta’sir, dalil va so‘ralgan yechim. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Booking complaint email: tekshiriladigan fakt, ta’sir, dalil va so‘ralgan yechim.","exit":[[{"id":"en-b2-23-exit0","type":"grammarFill","skill":"grammar","prompt":"I am writing ___ our booking.","answers":["about"],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action"},{"id":"en-b2-23-exit1","type":"grammarFill","skill":"grammar","prompt":"The delay ___ our meeting. (affect, past)","answers":["affected"],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action"},{"id":"en-b2-23-exit2","type":"grammarFill","skill":"grammar","prompt":"Could you ___ the cause? (explain)","answers":["explain"],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action"},{"id":"en-b2-23-exit3","type":"choice","skill":"grammar","prompt":"Intention claim nega o‘zgartirildi?","answers":["dishonesty was not supported by evidence"],"explanation":"Motiv dalili yo‘q.","hint":"problem → impact → evidence → requested action","options":["dishonesty was not supported by evidence","there was no delay","politeness forbids complaints"]},{"id":"en-b2-23-exit4","type":"choice","skill":"grammar","prompt":"Revised complaint maqsadi?","answers":["a practical solution and explanation"],"explanation":"Keyingi booking aniqligi.","hint":"problem → impact → evidence → requested action","options":["a practical solution and explanation","stronger insults","hide the confirmation"]}],[{"id":"en-b2-23-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The room was not available at the agreed time."],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action","tokens":["The","room","was","not","available","at","the","agreed","time."]},{"id":"en-b2-23-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The delay ___ our meeting. (affect, past)","answers":["affected"],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action"},{"id":"en-b2-23-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The confirmation email gives a start time of ten."],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action","tokens":["The","confirmation","email","gives","a","start","time","of","ten."]},{"id":"en-b2-23-exit-b3","type":"choice","skill":"grammar","prompt":"Intention claim nega o‘zgartirildi?","answers":["dishonesty was not supported by evidence"],"explanation":"Motiv dalili yo‘q.","hint":"problem → impact → evidence → requested action","options":["dishonesty was not supported by evidence","there was no delay","politeness forbids complaints"]},{"id":"en-b2-23-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I would appreciate a clear response by Friday."],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action","tokens":["I","would","appreciate","a","clear","response","by","Friday."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-24','en-b2-24',null,4,24,'published',1,'{"id":"en-b2-24","baseId":"en-b2-24","revision":1,"level":"B2","levelIndex":4,"order":24,"title":"Birgalikda qaror: B2 loyiha","objective":"Manbalarni qiyoslab, murosaga kelgan tavsiyani himoya qilasiz.","context":"Birgalikda qaror: B2 loyiha","prerequisites":["en-b2-23"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi.","Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi.","Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning."],"pattern":"compare criteria → weigh options → agree → review","examples":["We need to weigh up the options.","Could we agree on the main criteria?","The cheaper plan may exclude some users.","The flexible plan costs more but reaches more people.","Let us try a compromise for two weeks.","We will review the decision using attendance data."],"vocabulary":[{"id":"en-b2-24-v0","term":"weigh up","meaning":"solishtirib baholamoq","ipa":"/weɪ ʌp/","collocation":"weigh up options","example":"We need to weigh up the options."},{"id":"en-b2-24-v1","term":"compromise","meaning":"murosa","ipa":"/ˈkɒmprəmaɪz/","collocation":"reach a compromise","example":"Let us try a compromise for two weeks."},{"id":"en-b2-24-v2","term":"priority","meaning":"ustuvorlik","ipa":"/praɪˈɒrəti/","collocation":"agree on priorities","example":"agree on priorities"},{"id":"en-b2-24-v3","term":"feasible","meaning":"amalga oshadigan","ipa":"/ˈfiːzəbəl/","collocation":"a feasible plan","example":"a feasible plan"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["compare criteria → weigh options → agree → review","We need to weigh up the options.","Could we agree on the main criteria?"]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Survey and interviews reveal different needs.","The committee agrees on shared criteria.","Test a compromise and review the evidence."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The flexible plan costs more but reaches more people.","audio":"/english-course/v7.23/en-b2-24-dictation.mp3"},"exercises":[{"id":"en-b2-24-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: We need to weigh ___ the options.","answers":["up"],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review","options":["up","off","on"]},{"id":"en-b2-24-gap","type":"grammarFill","skill":"grammar","prompt":"We need to weigh ___ the options.","answers":["up"],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review"},{"id":"en-b2-24-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We need to weigh up the options."],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review","tokens":["We","need","to","weigh","up","the","options."]},{"id":"en-b2-24-fix","type":"correction","skill":"grammar","prompt":"More survey replies mean every other need is irrelevant.","answers":["More survey replies are useful, but other needs still require consideration."],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review"},{"id":"en-b2-24-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["solishtirib baholamoq","murosa","ustuvorlik","amalga oshadigan"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"compare criteria → weigh options → agree → review","left":["weigh up","compromise","priority","feasible"],"options":["solishtirib baholamoq","murosa","ustuvorlik","amalga oshadigan"]},{"id":"en-b2-24-transform","type":"transformation","skill":"grammar","prompt":"Murosa taklif qiling: We could test both afternoons.","answers":["Let us try a compromise using both afternoons."],"hint":"compare criteria → weigh options → agree → review","explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi."},{"id":"en-b2-24-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Survey and interviews reveal different needs.","The committee agrees on shared criteria.","Test a compromise and review the evidence."],"answers":["Survey and interviews reveal different needs.\nThe committee agrees on shared criteria.\nTest a compromise and review the evidence."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-24-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["weigh up","compromise","priority","feasible"],"options":["weigh up options","reach a compromise","agree on priorities","a feasible plan"],"answers":["weigh up options","reach a compromise","agree on priorities","a feasible plan"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."},{"id":"en-b2-24-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["We need to weigh up the options."],"tokens":["We","need","to","weigh","up","the","options."],"hint":"compare criteria → weigh options → agree → review","explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi."},{"id":"en-b2-24-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Opinion essay: dalil va qarshi fikr: Til vositasini tanlang: Critics reasonably ___ out the cost. (point)","answers":["point"],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["point","points","pointing"],"recap":true,"sourceLesson":"Opinion essay: dalil va qarshi fikr"},{"id":"en-b2-24-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Report va review: maqsad farqi: Til vositasini tanlang: The review ___ the guide. (evaluate)","answers":["evaluates"],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation","options":["evaluates","evaluate","evaluating"],"recap":true,"sourceLesson":"Report va review: maqsad farqi"},{"id":"en-b2-24-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Formal complaint va request: Til vositasini tanlang: I am writing ___ our booking.","answers":["about"],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action","options":["about","at","of"],"recap":true,"sourceLesson":"Formal complaint va request"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The school club has funds for one extra session each week. A survey favours a fixed afternoon, while interviews with students who travel far suggest that a rotating day would be fairer. The survey has more responses, but the interviews reveal a need the fixed schedule may overlook. The committee first agrees on three criteria: access, cost, and reliable staffing. It then compares the options against those criteria instead of choosing the most popular answer automatically. The group proposes alternating two afternoons for a short trial. This compromise may not satisfy every preference, but it can test whether more students attend without increasing the total number of sessions. The decision includes a review date and a way to collect evidence. Agreement is stronger when participants understand both the benefit and the remaining limitation.","sentences":["The school club has funds for one extra session each week.","A survey favours a fixed afternoon, while interviews with students who travel far suggest that a rotating day would be fairer.","The survey has more responses, but the interviews reveal a need the fixed schedule may overlook.","The committee first agrees on three criteria: access, cost, and reliable staffing.","It then compares the options against those criteria instead of choosing the most popular answer automatically.","The group proposes alternating two afternoons for a short trial.","This compromise may not satisfy every preference, but it can test whether more students attend without increasing the total number of sessions.","The decision includes a review date and a way to collect evidence.","Agreement is stronger when participants understand both the benefit and the remaining limitation."],"questions":[{"id":"en-b2-24-reading0","type":"choice","skill":"reading","prompt":"Interviews qanday yangi ehtiyojni ochdi?","answers":["access for students who travel far"],"explanation":"Surveyda yo‘q access tafsiloti.","hint":"compare criteria → weigh options → agree → review","options":["access for students who travel far","a demand for no sessions","the exact staffing cost"]},{"id":"en-b2-24-reading1","type":"choice","skill":"reading","prompt":"Qaror nega review bilan?","answers":["the compromise still needs evidence"],"explanation":"Sinov natijasi tekshiriladi.","hint":"compare criteria → weigh options → agree → review","options":["the compromise still needs evidence","all uncertainty is gone","attendance never matters"]},{"id":"en-b2-24-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"compare criteria → weigh options → agree → review","options":["The school club has funds for one extra session each week.","A survey favours a fixed afternoon, while interviews with students who travel far suggest that a rotating day would be fairer.","The survey has more responses, but the interviews reveal a need the fixed schedule may overlook.","The committee first agrees on three criteria: access, cost, and reliable staffing.","It then compares the options against those criteria instead of choosing the most popular answer automatically.","The group proposes alternating two afternoons for a short trial.","This compromise may not satisfy every preference, but it can test whether more students attend without increasing the total number of sessions.","The decision includes a review date and a way to collect evidence.","Agreement is stronger when participants understand both the benefit and the remaining limitation."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is priority. The school club has funds for one extra session each week. A survey favours a fixed afternoon, while interviews with students who travel far suggest that a rotating day would be fairer. Speaker two: My main point is compromise. Agree on criteria before choosing the most popular option. The school club has funds for one extra session each week. A survey favours a fixed afternoon, while interviews with students who travel far suggest that a rotating day would be fairer. The survey has more responses, but the interviews reveal a need the fixed schedule may overlook. The committee first agrees on three criteria: access, cost, and reliable staffing. It then compares the options against those criteria instead of choosing the most popular answer automatically. The group proposes alternating two afternoons for a short trial. This compromise may not satisfy every preference, but it can test whether more students attend without increasing the total number of sessions. The decision includes a review date and a way to collect evidence. Agreement is stronger when participants understand both the benefit and the remaining limitation.","audio":"/english-course/v7.23/en-b2-24.mp3","synthetic":true,"questions":[{"id":"en-b2-24-listening0","type":"choice","skill":"listening","prompt":"Interviews qanday yangi ehtiyojni ochdi?","answers":["access for students who travel far"],"explanation":"Surveyda yo‘q access tafsiloti.","hint":"compare criteria → weigh options → agree → review","options":["access for students who travel far","a demand for no sessions","the exact staffing cost"]},{"id":"en-b2-24-listening1","type":"choice","skill":"listening","prompt":"Qaror nega review bilan?","answers":["the compromise still needs evidence"],"explanation":"Sinov natijasi tekshiriladi.","hint":"compare criteria → weigh options → agree → review","options":["the compromise still needs evidence","all uncertainty is gone","attendance never matters"]},{"id":"en-b2-24-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["priority","compromise"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"compare criteria → weigh options → agree → review","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-24-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The flexible plan costs more but reaches more people."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"compare criteria → weigh options → agree → review","audio":"/english-course/v7.23/en-b2-24-dictation.mp3","transcript":"The flexible plan costs more but reaches more people."}]},"writing":{"task":"B2 yakuniy loyiha: survey va interviewni qiyoslab committee report yozing, keyin qarorni og‘zaki himoya qiling.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"We recommend alternating two afternoons for a two-week trial. The survey favours a fixed day, but interviews show that students who travel far may need greater flexibility. We compared the options using access, cost, and staffing as criteria. Alternating days preserves one session per week while testing whether attendance becomes broader. This is a compromise, not proof that everyone will be satisfied. The committee should record attendance and ask students whether the change helps them participate. At the review meeting, we can retain, revise, or reject the arrangement based on evidence rather than preference alone.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["We need to weigh up the options.","Could we agree on the main criteria?","The cheaper plan may exclude some users."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. B2 yakuniy loyiha: survey va interviewni qiyoslab committee report yozing, keyin qarorni og‘zaki himoya qiling. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"B2 yakuniy loyiha: survey va interviewni qiyoslab committee report yozing, keyin qarorni og‘zaki himoya qiling.","exit":[[{"id":"en-b2-24-exit0","type":"grammarFill","skill":"grammar","prompt":"We need to weigh ___ the options.","answers":["up"],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review"},{"id":"en-b2-24-exit1","type":"grammarFill","skill":"grammar","prompt":"Could we agree ___ criteria?","answers":["on"],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review"},{"id":"en-b2-24-exit2","type":"grammarFill","skill":"grammar","prompt":"We will ___ the decision. (review)","answers":["review"],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review"},{"id":"en-b2-24-exit3","type":"choice","skill":"grammar","prompt":"Interviews qanday yangi ehtiyojni ochdi?","answers":["access for students who travel far"],"explanation":"Surveyda yo‘q access tafsiloti.","hint":"compare criteria → weigh options → agree → review","options":["access for students who travel far","a demand for no sessions","the exact staffing cost"]},{"id":"en-b2-24-exit4","type":"choice","skill":"grammar","prompt":"Qaror nega review bilan?","answers":["the compromise still needs evidence"],"explanation":"Sinov natijasi tekshiriladi.","hint":"compare criteria → weigh options → agree → review","options":["the compromise still needs evidence","all uncertainty is gone","attendance never matters"]}],[{"id":"en-b2-24-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Could we agree on the main criteria?"],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review","tokens":["Could","we","agree","on","the","main","criteria?"]},{"id":"en-b2-24-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Could we agree ___ criteria?","answers":["on"],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review"},{"id":"en-b2-24-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The flexible plan costs more but reaches more people."],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review","tokens":["The","flexible","plan","costs","more","but","reaches","more","people."]},{"id":"en-b2-24-exit-b3","type":"choice","skill":"grammar","prompt":"Interviews qanday yangi ehtiyojni ochdi?","answers":["access for students who travel far"],"explanation":"Surveyda yo‘q access tafsiloti.","hint":"compare criteria → weigh options → agree → review","options":["access for students who travel far","a demand for no sessions","the exact staffing cost"]},{"id":"en-b2-24-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We will review the decision using attendance data."],"explanation":"Bitta variantning foydasi boshqa ehtiyojni yo‘qqa chiqarmaydi. Weigh up options, agree on criteria, reach a compromise suhbatni qarorga olib boradi. Decision qayta ko‘riladigan mezon va muddat bilan mustahkamlanadi; dalilsiz qat’iylikdan saqlaning.","hint":"compare criteria → weigh options → agree → review","tokens":["We","will","review","the","decision","using","attendance","data."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"b2-natural","name":"British Council — A business interview","levels":["B2"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening/b2/business-interview","task":"Tabiiy intervyuda maqsad, suhbatdosh pozitsiyasi va ikki tafsilotni qayd eting.","lesson":"en-b2-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":true,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-b2-24-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Opinion essay: dalil va qarshi fikr: Til vositasini tanlang: Critics reasonably ___ out the cost. (point)","answers":["point"],"explanation":"Opinion essay da’vosi aniq, paragraphs bir sababni rivojlantiradi. Misolning da’voga qanday aloqasi borligini tushuntiring; faqat example sanamang. Counterargumentni kuchsiz qilib ko‘rsatmang: uning asosli qismini tan olib javob bering.","hint":"claim → evidence → explanation → counterargument → conclusion","options":["point","points","pointing"],"recap":true,"sourceLesson":"Opinion essay: dalil va qarshi fikr"},{"id":"en-b2-24-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Report va review: maqsad farqi: Til vositasini tanlang: The review ___ the guide. (evaluate)","answers":["evaluates"],"explanation":"Report maqsad, dalil, natija va tavsiya; review tajriba va mezon asosidagi baho. Baho subyektiv bo‘lsa uning mezonini ochiq ayting. Sarlavhalar reportni skanerlashga yordam beradi; review ham faktni xolis saqlashi kerak.","hint":"findings → recommendation / experience → evaluation","options":["evaluates","evaluate","evaluating"],"recap":true,"sourceLesson":"Report va review: maqsad farqi"},{"id":"en-b2-24-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Formal complaint va request: Til vositasini tanlang: I am writing ___ our booking.","answers":["about"],"explanation":"Complaint fakt va ta’sirni ajratadi; haqorat yechimga yordam bermaydi. I would appreciate …, could you confirm … bilan so‘ralgan amal aniq bo‘lsin. Muddat va dalilni ayting, lekin mavjud bo‘lmagan huquq yoki kafolatni o‘ylab topmang.","hint":"problem → impact → evidence → requested action","options":["about","at","of"],"recap":true,"sourceLesson":"Formal complaint va request"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-01','en-c1-01',null,5,1,'published',1,'{"id":"en-c1-01","baseId":"en-c1-01","revision":1,"level":"C1","levelIndex":5,"order":1,"title":"Grammatik tanlov va muallif pozitsiyasi","objective":"Shakl o‘zgarishi sabab, mas’uliyat va ishonchni qanday ko‘rsatishini tahlil qilasiz.","context":"Grammatik tanlov va muallif pozitsiyasi","prerequisites":["en-b2-24"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak.","Aspect davomiylik, natija va vaqt chegarasini belgilaydi.","Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang."],"pattern":"the committee delayed / the decision was delayed / has been reconsidering","examples":["The committee delayed the decision.","The decision was delayed pending consultation.","The committee has been reconsidering its criteria.","The criteria have been revised twice.","The wording may shift attention away from the agent.","That effect does not establish the writer’s intention."],"vocabulary":[{"id":"en-c1-01-v0","term":"agency","meaning":"bajaruvchi roli","ipa":"/ˈeɪdʒənsi/","collocation":"obscure agency","example":"obscure agency"},{"id":"en-c1-01-v1","term":"stance","meaning":"pozitsiya","ipa":"/stɑːns/","collocation":"signal a stance","example":"signal a stance"},{"id":"en-c1-01-v2","term":"implication","meaning":"anglashilgan ma’no","ipa":"/ˌɪmplɪˈkeɪʃən/","collocation":"a possible implication","example":"a possible implication"},{"id":"en-c1-01-v3","term":"attribution","meaning":"tegishlilik","ipa":"/ˌætrɪˈbjuːʃən/","collocation":"clear attribution","example":"This makes criticism more precise: readers can request clearer attribution without claiming to know why the writer chose a particular form."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["the committee delayed / the decision was delayed / has been reconsidering","The committee delayed the decision.","The decision was delayed pending consultation."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Wording shifts attention.","Different aspects describe results and continuing work.","Separate effect from speculation about intention."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The criteria have been revised twice.","audio":"/english-course/v7.23/en-c1-01-dictation.mp3"},"exercises":[{"id":"en-c1-01-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Criteria have been ___ twice. (revise)","answers":["revised"],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering","options":["revised","revising","revise"]},{"id":"en-c1-01-gap","type":"grammarFill","skill":"grammar","prompt":"Criteria have been ___ twice. (revise)","answers":["revised"],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering"},{"id":"en-c1-01-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The committee delayed the decision."],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering","tokens":["The","committee","delayed","the","decision."]},{"id":"en-c1-01-fix","type":"correction","skill":"grammar","prompt":"The passive proves that the writer intended to deceive.","answers":["The passive may shift attention, but it does not prove an intention to deceive."],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering"},{"id":"en-c1-01-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["bajaruvchi roli","pozitsiya","anglashilgan ma’no","tegishlilik"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"the committee delayed / the decision was delayed / has been reconsidering","left":["agency","stance","implication","attribution"],"options":["bajaruvchi roli","pozitsiya","anglashilgan ma’no","tegishlilik"]},{"id":"en-c1-01-transform","type":"transformation","skill":"grammar","prompt":"Agent markazda: The decision was delayed by the committee.","answers":["The committee delayed the decision."],"hint":"the committee delayed / the decision was delayed / has been reconsidering","explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak."},{"id":"en-c1-01-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Wording shifts attention.","Different aspects describe results and continuing work.","Separate effect from speculation about intention."],"answers":["Wording shifts attention.\nDifferent aspects describe results and continuing work.\nSeparate effect from speculation about intention."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Two versions of a council notice describe the same delay. The first says that the committee postponed a decision; the second says that the decision was postponed pending consultation. The passive version directs attention to the process rather than the committee. A reader might interpret this as avoidance of responsibility, but the wording alone cannot establish that intention. The notice also says that criteria have been revised twice, presenting a measurable result, whereas another sentence says that members have been reconsidering their priorities, foregrounding continuing work. A careful analysis distinguishes grammatical effect, supported inference, and speculation about motives. This makes criticism more precise: readers can request clearer attribution without claiming to know why the writer chose a particular form.","sentences":["Two versions of a council notice describe the same delay.","The first says that the committee postponed a decision; the second says that the decision was postponed pending consultation.","The passive version directs attention to the process rather than the committee.","A reader might interpret this as avoidance of responsibility, but the wording alone cannot establish that intention.","The notice also says that criteria have been revised twice, presenting a measurable result, whereas another sentence says that members have been reconsidering their priorities, foregrounding continuing work.","A careful analysis distinguishes grammatical effect, supported inference, and speculation about motives.","This makes criticism more precise: readers can request clearer attribution without claiming to know why the writer chose a particular form."],"questions":[{"id":"en-c1-01-reading0","type":"choice","skill":"reading","prompt":"Passive qanday ta’sir beradi?","answers":["it foregrounds process"],"explanation":"E’tibor jarayonga.","hint":"the committee delayed / the decision was delayed / has been reconsidering","options":["it foregrounds process","it proves dishonesty","it changes the historical date"]},{"id":"en-c1-01-reading1","type":"choice","skill":"reading","prompt":"Muallif motiviga nima yetmaydi?","answers":["independent evidence"],"explanation":"Shaklning o‘zi niyat dalili emas.","hint":"the committee delayed / the decision was delayed / has been reconsidering","options":["independent evidence","a passive form","two versions"]},{"id":"en-c1-01-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"the committee delayed / the decision was delayed / has been reconsidering","options":["Two versions of a council notice describe the same delay.","The first says that the committee postponed a decision; the second says that the decision was postponed pending consultation.","The passive version directs attention to the process rather than the committee.","A reader might interpret this as avoidance of responsibility, but the wording alone cannot establish that intention.","The notice also says that criteria have been revised twice, presenting a measurable result, whereas another sentence says that members have been reconsidering their priorities, foregrounding continuing work.","A careful analysis distinguishes grammatical effect, supported inference, and speculation about motives.","This makes criticism more precise: readers can request clearer attribution without claiming to know why the writer chose a particular form."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is agency. Two versions of a council notice describe the same delay. The first says that the committee postponed a decision; the second says that the decision was postponed pending consultation. Speaker two: My main point is attribution. Ask for clearer attribution without pretending to know the writer’s motives. Two versions of a council notice describe the same delay. The first says that the committee postponed a decision; the second says that the decision was postponed pending consultation. The passive version directs attention to the process rather than the committee. A reader might interpret this as avoidance of responsibility, but the wording alone cannot establish that intention. The notice also says that criteria have been revised twice, presenting a measurable result, whereas another sentence says that members have been reconsidering their priorities, foregrounding continuing work. A careful analysis distinguishes grammatical effect, supported inference, and speculation about motives. This makes criticism more precise: readers can request clearer attribution without claiming to know why the writer chose a particular form.","audio":"/english-course/v7.23/en-c1-01.mp3","synthetic":true,"questions":[{"id":"en-c1-01-listening0","type":"choice","skill":"listening","prompt":"Passive qanday ta’sir beradi?","answers":["it foregrounds process"],"explanation":"E’tibor jarayonga.","hint":"the committee delayed / the decision was delayed / has been reconsidering","options":["it foregrounds process","it proves dishonesty","it changes the historical date"]},{"id":"en-c1-01-listening1","type":"choice","skill":"listening","prompt":"Muallif motiviga nima yetmaydi?","answers":["independent evidence"],"explanation":"Shaklning o‘zi niyat dalili emas.","hint":"the committee delayed / the decision was delayed / has been reconsidering","options":["independent evidence","a passive form","two versions"]},{"id":"en-c1-01-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["agency","attribution"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-01-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The criteria have been revised twice."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"the committee delayed / the decision was delayed / has been reconsidering","audio":"/english-course/v7.23/en-c1-01-dictation.mp3","transcript":"The criteria have been revised twice."}]},"writing":{"task":"Ikki notice uslubini tahlil qiling: grammatik ta’sir, dalil va ehtiyotkor inference.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The revised notice foregrounds the consultation process by using a passive clause. This reduces the prominence of the committee, but it does not establish an intention to avoid responsibility. The perfect simple describes two completed revisions, while the continuous form presents ongoing reconsideration. I would request a named contact and a review date. These changes would improve attribution and practical clarity without requiring a claim about motives that the text cannot substantiate.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The committee delayed the decision.","The decision was delayed pending consultation.","The committee has been reconsidering its criteria."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Ikki notice uslubini tahlil qiling: grammatik ta’sir, dalil va ehtiyotkor inference. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Ikki notice uslubini tahlil qiling: grammatik ta’sir, dalil va ehtiyotkor inference.","exit":[[{"id":"en-c1-01-exit0","type":"grammarFill","skill":"grammar","prompt":"Criteria have been ___ twice. (revise)","answers":["revised"],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering"},{"id":"en-c1-01-exit1","type":"grammarFill","skill":"grammar","prompt":"Members have been ___ priorities. (reconsider)","answers":["reconsidering"],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering"},{"id":"en-c1-01-exit2","type":"grammarFill","skill":"grammar","prompt":"The wording may ___ attention. (shift)","answers":["shift"],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering"},{"id":"en-c1-01-exit3","type":"choice","skill":"grammar","prompt":"Passive qanday ta’sir beradi?","answers":["it foregrounds process"],"explanation":"E’tibor jarayonga.","hint":"the committee delayed / the decision was delayed / has been reconsidering","options":["it foregrounds process","it proves dishonesty","it changes the historical date"]},{"id":"en-c1-01-exit4","type":"choice","skill":"grammar","prompt":"Muallif motiviga nima yetmaydi?","answers":["independent evidence"],"explanation":"Shaklning o‘zi niyat dalili emas.","hint":"the committee delayed / the decision was delayed / has been reconsidering","options":["independent evidence","a passive form","two versions"]}],[{"id":"en-c1-01-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The decision was delayed pending consultation."],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering","tokens":["The","decision","was","delayed","pending","consultation."]},{"id":"en-c1-01-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Members have been ___ priorities. (reconsider)","answers":["reconsidering"],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering"},{"id":"en-c1-01-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The criteria have been revised twice."],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering","tokens":["The","criteria","have","been","revised","twice."]},{"id":"en-c1-01-exit-b3","type":"choice","skill":"grammar","prompt":"Passive qanday ta’sir beradi?","answers":["it foregrounds process"],"explanation":"E’tibor jarayonga.","hint":"the committee delayed / the decision was delayed / has been reconsidering","options":["it foregrounds process","it proves dishonesty","it changes the historical date"]},{"id":"en-c1-01-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["That effect does not establish the writer’s intention."],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering","tokens":["That","effect","does","not","establish","the","writer’s","intention."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-02','en-c1-02',null,5,2,'published',1,'{"id":"en-c1-02","baseId":"en-c1-02","revision":1,"level":"C1","levelIndex":5,"order":2,"title":"Negative adverbialdan keyingi inversion","objective":"Cheklov va ta’kidni inversion bilan maqsadli ifodalaysiz.","context":"Negative adverbialdan keyingi inversion","prerequisites":["en-c1-01"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin.","Not until bilan inversion asosiy gapda: Not until … did we understand.","Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang."],"pattern":"Rarely have … / Not until … did …","examples":["Rarely have we seen such agreement.","Never had the group discussed access so carefully.","Under no circumstances should names be published.","Not until the review did we understand the limitation.","Only after consultation did they revise the plan.","No sooner had we begun than the alarm sounded."],"vocabulary":[{"id":"en-c1-02-v0","term":"restriction","meaning":"cheklov","ipa":"/rɪˈstrɪkʃən/","collocation":"state a restriction","example":"A privacy note uses a stronger restriction: “Under no circumstances should names be published without permission.” Here inversion highlights an operational rule rather than an emotional reaction."},{"id":"en-c1-02-v1","term":"emphasis","meaning":"ta’kid","ipa":"/ˈemfəsɪs/","collocation":"place emphasis","example":"A seminar summary opens, “Rarely have participants agreed so quickly.” The sentence creates emphasis, but the writer later reveals that only six people attended."},{"id":"en-c1-02-v2","term":"exception","meaning":"istisno","ipa":"/ɪkˈsepʃən/","collocation":"a rare exception","example":"a rare exception"},{"id":"en-c1-02-v3","term":"safeguard","meaning":"himoya chorasi","ipa":"/ˈseɪfɡɑːd/","collocation":"a privacy safeguard","example":"a privacy safeguard"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["Rarely have … / Not until … did …","Rarely have we seen such agreement.","Never had the group discussed access so carefully."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Emphasis needs a defined scope.","Six participants agreed at one seminar.","Keep strong wording for justified observations and rules."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Not until the review did we understand the limitation.","audio":"/english-course/v7.23/en-c1-02-dictation.mp3"},"exercises":[{"id":"en-c1-02-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Rarely ___ we seen such agreement.","answers":["have"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","options":["have","has","had"]},{"id":"en-c1-02-gap","type":"grammarFill","skill":"grammar","prompt":"Rarely ___ we seen such agreement.","answers":["have"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Rarely have we seen such agreement."],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","tokens":["Rarely","have","we","seen","such","agreement."]},{"id":"en-c1-02-fix","type":"correction","skill":"grammar","prompt":"Rarely we have seen such agreement.","answers":["Rarely have we seen such agreement."],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["cheklov","ta’kid","istisno","himoya chorasi"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Rarely have … / Not until … did …","left":["restriction","emphasis","exception","safeguard"],"options":["cheklov","ta’kid","istisno","himoya chorasi"]},{"id":"en-c1-02-transform","type":"transformation","skill":"grammar","prompt":"Only after boshida: They revised the plan only after consultation.","answers":["Only after consultation did they revise the plan."],"hint":"Rarely have … / Not until … did …","explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin."},{"id":"en-c1-02-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Emphasis needs a defined scope.","Six participants agreed at one seminar.","Keep strong wording for justified observations and rules."],"answers":["Emphasis needs a defined scope.\nSix participants agreed at one seminar.\nKeep strong wording for justified observations and rules."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A seminar summary opens, “Rarely have participants agreed so quickly.” The sentence creates emphasis, but the writer later reveals that only six people attended. The claim is therefore about this seminar history, not a universal pattern. A privacy note uses a stronger restriction: “Under no circumstances should names be published without permission.” Here inversion highlights an operational rule rather than an emotional reaction. The editor keeps that emphasis and simplifies a third inverted sentence because it interrupts the explanation. Advanced grammar earns its place when it supports a communicative purpose. A reader should be able to say what is being restricted, when understanding changed, or why emphasis matters. Unnecessary inversion can make ordinary information sound more dramatic than its evidence warrants.","sentences":["A seminar summary opens, “Rarely have participants agreed so quickly.","” The sentence creates emphasis, but the writer later reveals that only six people attended.","The claim is therefore about this seminar history, not a universal pattern.","A privacy note uses a stronger restriction: “Under no circumstances should names be published without permission.","” Here inversion highlights an operational rule rather than an emotional reaction.","The editor keeps that emphasis and simplifies a third inverted sentence because it interrupts the explanation.","Advanced grammar earns its place when it supports a communicative purpose.","A reader should be able to say what is being restricted, when understanding changed, or why emphasis matters.","Unnecessary inversion can make ordinary information sound more dramatic than its evidence warrants."],"questions":[{"id":"en-c1-02-reading0","type":"choice","skill":"reading","prompt":"Privacy inversion vazifasi?","answers":["highlight an operational restriction"],"explanation":"Qoidani ta’kidlaydi.","hint":"Rarely have … / Not until … did …","options":["highlight an operational restriction","prove a universal survey result","describe six names"]},{"id":"en-c1-02-reading1","type":"choice","skill":"reading","prompt":"Editor nega bir gapni soddalashtirdi?","answers":["its emphasis obstructed explanation"],"explanation":"Maqsadsiz ta’kid o‘qishga halal.","hint":"Rarely have … / Not until … did …","options":["its emphasis obstructed explanation","inversion is always wrong","all information was false"]},{"id":"en-c1-02-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Rarely have … / Not until … did …","options":["A seminar summary opens, “Rarely have participants agreed so quickly.","” The sentence creates emphasis, but the writer later reveals that only six people attended.","The claim is therefore about this seminar history, not a universal pattern.","A privacy note uses a stronger restriction: “Under no circumstances should names be published without permission.","” Here inversion highlights an operational rule rather than an emotional reaction.","The editor keeps that emphasis and simplifies a third inverted sentence because it interrupts the explanation.","Advanced grammar earns its place when it supports a communicative purpose.","A reader should be able to say what is being restricted, when understanding changed, or why emphasis matters.","Unnecessary inversion can make ordinary information sound more dramatic than its evidence warrants."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is restriction. A seminar summary opens, “Rarely have participants agreed so quickly. ” The sentence creates emphasis, but the writer later reveals that only six people attended. Speaker two: My main point is purpose. Use inversion when the communicative purpose justifies the emphasis. A seminar summary opens, “Rarely have participants agreed so quickly.” The sentence creates emphasis, but the writer later reveals that only six people attended. The claim is therefore about this seminar history, not a universal pattern. A privacy note uses a stronger restriction: “Under no circumstances should names be published without permission.” Here inversion highlights an operational rule rather than an emotional reaction. The editor keeps that emphasis and simplifies a third inverted sentence because it interrupts the explanation. Advanced grammar earns its place when it supports a communicative purpose. A reader should be able to say what is being restricted, when understanding changed, or why emphasis matters. Unnecessary inversion can make ordinary information sound more dramatic than its evidence warrants.","audio":"/english-course/v7.23/en-c1-02.mp3","synthetic":true,"questions":[{"id":"en-c1-02-listening0","type":"choice","skill":"listening","prompt":"Privacy inversion vazifasi?","answers":["highlight an operational restriction"],"explanation":"Qoidani ta’kidlaydi.","hint":"Rarely have … / Not until … did …","options":["highlight an operational restriction","prove a universal survey result","describe six names"]},{"id":"en-c1-02-listening1","type":"choice","skill":"listening","prompt":"Editor nega bir gapni soddalashtirdi?","answers":["its emphasis obstructed explanation"],"explanation":"Maqsadsiz ta’kid o‘qishga halal.","hint":"Rarely have … / Not until … did …","options":["its emphasis obstructed explanation","inversion is always wrong","all information was false"]},{"id":"en-c1-02-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["restriction","purpose"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Rarely have … / Not until … did …","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-02-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Not until the review did we understand the limitation."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Rarely have … / Not until … did …","audio":"/english-course/v7.23/en-c1-02-dictation.mp3","transcript":"Not until the review did we understand the limitation."}]},"writing":{"task":"Seminar summary yozing; ikkita inversion va ularning vazifasini alohida izohlang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Rarely have participants reached agreement so quickly, although the meeting involved only six people. The result should therefore be interpreted within that limited setting. Only after consultation did the committee revise the access criteria. This emphasis highlights the sequence that made the revision possible. Under no circumstances should participants’ names be published without permission. Unlike the opening observation, this final sentence states a restriction, so its strong emphasis serves a practical purpose rather than exaggerating the findings.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["Rarely have we seen such agreement.","Never had the group discussed access so carefully.","Under no circumstances should names be published."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Seminar summary yozing; ikkita inversion va ularning vazifasini alohida izohlang. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Seminar summary yozing; ikkita inversion va ularning vazifasini alohida izohlang.","exit":[[{"id":"en-c1-02-exit0","type":"grammarFill","skill":"grammar","prompt":"Rarely ___ we seen such agreement.","answers":["have"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-exit1","type":"grammarFill","skill":"grammar","prompt":"Not until the review ___ we understand.","answers":["did"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-exit2","type":"grammarFill","skill":"grammar","prompt":"Under no circumstances ___ names be published.","answers":["should"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-exit3","type":"choice","skill":"grammar","prompt":"Privacy inversion vazifasi?","answers":["highlight an operational restriction"],"explanation":"Qoidani ta’kidlaydi.","hint":"Rarely have … / Not until … did …","options":["highlight an operational restriction","prove a universal survey result","describe six names"]},{"id":"en-c1-02-exit4","type":"choice","skill":"grammar","prompt":"Editor nega bir gapni soddalashtirdi?","answers":["its emphasis obstructed explanation"],"explanation":"Maqsadsiz ta’kid o‘qishga halal.","hint":"Rarely have … / Not until … did …","options":["its emphasis obstructed explanation","inversion is always wrong","all information was false"]}],[{"id":"en-c1-02-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Never had the group discussed access so carefully."],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","tokens":["Never","had","the","group","discussed","access","so","carefully."]},{"id":"en-c1-02-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Not until the review ___ we understand.","answers":["did"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Not until the review did we understand the limitation."],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","tokens":["Not","until","the","review","did","we","understand","the","limitation."]},{"id":"en-c1-02-exit-b3","type":"choice","skill":"grammar","prompt":"Privacy inversion vazifasi?","answers":["highlight an operational restriction"],"explanation":"Qoidani ta’kidlaydi.","hint":"Rarely have … / Not until … did …","options":["highlight an operational restriction","prove a universal survey result","describe six names"]},{"id":"en-c1-02-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["No sooner had we begun than the alarm sounded."],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","tokens":["No","sooner","had","we","begun","than","the","alarm","sounded."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flit